window.__qzParts=window.__qzParts||{};window.__qzParts.hoahoc=[{"p":"Hạt nào trong nguyên tử mang điện tích dương?","o":["Electron","Proton","Neutron","Không có hạt nào trong nguyên tử mang điện"],"a":"Proton","h":"Hạt nhân gồm proton và neutron; electron ở vỏ nguyên tử mang điện âm.","e":"Proton nằm trong hạt nhân và mang điện tích dương (+1). Electron mang điện tích âm, neutron không mang điện.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Vì sao nguyên tử trung hoà về điện?","o":["Vì số proton bằng số electron","Vì số neutron bằng số proton","Vì nguyên tử không chứa hạt mang điện nào","Vì số electron bằng số neutron"],"a":"Vì số proton bằng số electron","h":"Tổng điện tích dương của proton phải cân bằng với tổng điện tích âm của electron.","e":"Mỗi proton mang điện +1, mỗi electron mang điện -1. Khi số proton bằng số electron, tổng điện tích bằng 0 nên nguyên tử trung hoà về điện.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Một nguyên tử có số hiệu nguyên tử Z = 11 và số neutron N = 12. Số khối A của nguyên tử đó là","o":["11","12","23","1"],"a":"23","h":"Số khối A = Z + N.","e":"Số khối A = số proton + số neutron = Z + N = 11 + 12 = 23.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Đồng vị là những nguyên tử","o":["có cùng số khối nhưng khác số proton","có cùng số neutron nhưng khác số proton","thuộc các nguyên tố khác nhau nhưng có cùng số electron","có cùng số proton nhưng khác nhau về số neutron"],"a":"có cùng số proton nhưng khác nhau về số neutron","h":"Đồng vị thuộc cùng một nguyên tố hoá học.","e":"Đồng vị là những nguyên tử có cùng số proton (cùng số hiệu nguyên tử, cùng nguyên tố) nhưng khác số neutron nên khác số khối. Ví dụ: 12C và 14C.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Lớp electron thứ hai (lớp L) chứa tối đa bao nhiêu electron?","o":["2","8","18","32"],"a":"8","h":"Số electron tối đa của lớp thứ n là 2n^2.","e":"Lớp thứ n chứa tối đa 2n^2 electron. Lớp L là lớp thứ hai (n = 2) nên chứa tối đa 2 x 2^2 = 8 electron.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Nguyên tử của một nguyên tố có 6 proton và 7 neutron. Số khối của nguyên tử và số electron của nó (ở trạng thái trung hoà) lần lượt là","o":["6 và 7","7 và 6","13 và 6","13 và 7"],"a":"13 và 6","h":"Số khối A = số proton + số neutron; nguyên tử trung hoà có số electron bằng số proton.","e":"A = 6 + 7 = 13. Nguyên tử trung hoà về điện nên số electron = số proton = 6. Đây là nguyên tử carbon (C).","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Cách phân bố electron vào các lớp của nguyên tử natri (Na, Z = 11) là","o":["2, 8, 1","2, 8, 2","2, 9","8, 2, 1"],"a":"2, 8, 1","h":"Điền electron từ lớp trong ra ngoài: lớp 1 tối đa 2, lớp 2 tối đa 8, phần còn lại vào lớp 3.","e":"Na có 11 electron: lớp thứ nhất 2 electron, lớp thứ hai 8 electron, lớp thứ ba 1 electron. Vậy cấu hình theo lớp là 2, 8, 1.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Nguyên tử nhôm (Al, Z = 13) có số electron ở lớp ngoài cùng là","o":["1","3","8","13"],"a":"3","h":"Hãy viết cách phân bố 13 electron vào các lớp trước.","e":"Al có 13 electron, phân bố theo lớp là 2, 8, 3. Lớp ngoài cùng là lớp thứ ba, chứa 3 electron.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Orbital nguyên tử là","o":["quỹ đạo tròn cố định của electron quanh hạt nhân","đường đi chính xác của electron trong nguyên tử","khu vực không gian xung quanh hạt nhân mà xác suất tìm thấy electron là lớn nhất","lớp vỏ bao quanh hạt nhân nơi chứa các proton"],"a":"khu vực không gian xung quanh hạt nhân mà xác suất tìm thấy electron là lớn nhất","h":"Electron chuyển động rất nhanh và không theo một quỹ đạo xác định.","e":"Orbital nguyên tử là khu vực không gian xung quanh hạt nhân, trong đó xác suất tìm thấy electron là lớn nhất (khoảng 90%). Electron không chuyển động theo quỹ đạo cố định như hành tinh.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Các nguyên tố trong bảng tuần hoàn các nguyên tố hoá học được sắp xếp theo chiều tăng dần của","o":["điện tích hạt nhân nguyên tử","nguyên tử khối","số neutron trong hạt nhân","số lớp electron"],"a":"điện tích hạt nhân nguyên tử","h":"Đây là nguyên tắc sắp xếp cơ bản nhất của bảng tuần hoàn hiện đại.","e":"Bảng tuần hoàn hiện đại sắp xếp các nguyên tố theo chiều tăng dần của điện tích hạt nhân nguyên tử (tức tăng dần số hiệu nguyên tử Z).","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Ô nguyên tố trong bảng tuần hoàn cho biết thông tin nào sau đây?","o":["Chỉ cho biết tên của nguyên tố","Chỉ cho biết ký hiệu hoá học của nguyên tố","Cho biết nhiệt độ nóng chảy của đơn chất","Cho biết số hiệu nguyên tử, ký hiệu hoá học, tên và nguyên tử khối của nguyên tố"],"a":"Cho biết số hiệu nguyên tử, ký hiệu hoá học, tên và nguyên tử khối của nguyên tố","h":"Hãy nhớ lại hình ảnh một ô nguyên tố bất kỳ trong bảng tuần hoàn.","e":"Mỗi ô nguyên tố ghi: số hiệu nguyên tử (Z), ký hiệu hoá học, tên nguyên tố và nguyên tử khối trung bình. Ví dụ ô số 11 là natri (Na).","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Các nguyên tố trong cùng một chu kì có đặc điểm chung là","o":["có cùng số electron ở lớp ngoài cùng","có cùng số lớp electron","có tính chất hoá học giống nhau","đều là kim loại"],"a":"có cùng số lớp electron","h":"Số thứ tự của chu kì liên quan đến số lớp electron.","e":"Các nguyên tố trong cùng một chu kì có cùng số lớp electron; số thứ tự chu kì bằng số lớp electron. Ví dụ các nguyên tố chu kì 3 đều có 3 lớp electron.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Nguyên tố X nằm ở chu kì 3, nhóm IIA trong bảng tuần hoàn. Nguyên tử X có","o":["2 lớp electron và 3 electron ở lớp ngoài cùng","3 lớp electron và 3 electron ở lớp ngoài cùng","3 lớp electron và 2 electron ở lớp ngoài cùng","2 lớp electron và 2 electron ở lớp ngoài cùng"],"a":"3 lớp electron và 2 electron ở lớp ngoài cùng","h":"Chu kì cho biết số lớp electron; nhóm A cho biết số electron lớp ngoài cùng.","e":"Chu kì 3 nên nguyên tử X có 3 lớp electron. Nhóm IIA nên lớp ngoài cùng có 2 electron. X là magnesium (Mg).","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Trong bảng tuần hoàn, các khí hiếm nằm ở nhóm","o":["VIIIA","IA","VIIA","IIA"],"a":"VIIIA","h":"Khí hiếm có lớp electron ngoài cùng bền vững với 8 electron (trừ helium có 2).","e":"Các khí hiếm như He, Ne, Ar nằm ở nhóm VIIIA, phía ngoài cùng bên phải của bảng tuần hoàn. Cấu hình electron lớp ngoài cùng bền vững nên chúng rất trơ về hoá học.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong cùng một chu kì, khi đi từ trái sang phải, bán kính nguyên tử thường","o":["tăng dần","không đổi","thay đổi không theo quy luật nào","giảm dần"],"a":"giảm dần","h":"Trong một chu kì, số lớp electron không đổi nhưng điện tích hạt nhân tăng dần.","e":"Trong cùng chu kì, số lớp electron như nhau nhưng điện tích hạt nhân tăng dần nên lực hút electron của hạt nhân mạnh hơn, làm bán kính nguyên tử giảm dần.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Trong một nhóm A, khi đi từ trên xuống dưới, tính kim loại của các nguyên tố thường","o":["giảm dần","tăng dần","không thay đổi","lúc tăng lúc giảm, không có quy luật"],"a":"tăng dần","h":"Đi xuống dưới trong nhóm, nguyên tử có thêm lớp electron nên dễ nhường electron hơn.","e":"Trong một nhóm A, từ trên xuống dưới số lớp electron tăng, electron lớp ngoài cùng càng xa hạt nhân, càng dễ bị nhường đi nên tính kim loại tăng dần.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Theo quy tắc octet, khi hình thành liên kết hoá học, các nguyên tử có xu hướng đạt cấu hình electron bền vững của","o":["kim loại kiềm","halogen","khí hiếm","nguyên tử hiđro"],"a":"khí hiếm","h":"Đó là các nguyên tố có lớp electron ngoài cùng bền vững với 8 electron.","e":"Theo quy tắc octet, nguyên tử có xu hướng nhường, nhận hoặc góp chung electron để lớp ngoài cùng có 8 electron (2 với He) giống khí hiếm gần nhất, là cấu hình rất bền vững.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Khi hình thành phân tử NaCl từ các nguyên tử, sự thay đổi đúng là","o":["Na nhường 1 electron tạo thành Na+, Cl nhận 1 electron tạo thành Cl-","Na nhận 1 electron, Cl nhường 1 electron","Na và Cl góp chung một cặp electron","Na nhường 1 proton cho Cl"],"a":"Na nhường 1 electron tạo thành Na+, Cl nhận 1 electron tạo thành Cl-","h":"Na có 1 electron lớp ngoài cùng nên dễ nhường; Cl có 7 electron lớp ngoài cùng nên dễ nhận thêm 1.","e":"Na (2, 8, 1) nhường 1 electron thành Na+ có cấu hình giống Ne; Cl (2, 8, 7) nhận 1 electron thành Cl- có cấu hình giống Ar. Lực hút tĩnh điện giữa Na+ và Cl- tạo liên kết ion trong NaCl.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Liên kết cộng hoá trị được hình thành do","o":["sự nhường hẳn electron từ nguyên tử này sang nguyên tử khác","sự dùng chung một hay nhiều cặp electron giữa hai nguyên tử","lực hút giữa các ion mang điện trái dấu","sự chuyển proton giữa hai nguyên tử"],"a":"sự dùng chung một hay nhiều cặp electron giữa hai nguyên tử","h":"Từ khoá của loại liên kết này là 'góp chung'.","e":"Liên kết cộng hoá trị hình thành khi hai nguyên tử dùng chung một hay nhiều cặp electron, ví dụ trong H2, HCl, H2O. Cặp electron dùng chung bị hút bởi hạt nhân của cả hai nguyên tử.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong phân tử nước (H2O), nguyên tử O liên kết với hai nguyên tử H bằng","o":["hai liên kết ion","một liên kết ion và một liên kết cộng hoá trị","hai liên kết cộng hoá trị, mỗi liên kết là một cặp electron dùng chung giữa O và một nguyên tử H","liên kết kim loại"],"a":"hai liên kết cộng hoá trị, mỗi liên kết là một cặp electron dùng chung giữa O và một nguyên tử H","h":"O còn thiếu 2 electron để đạt octet; mỗi nguyên tử H góp 1 electron.","e":"O có 6 electron lớp ngoài cùng, cần thêm 2. Mỗi nguyên tử H góp chung với O một cặp electron, tạo hai liên kết cộng hoá trị O-H; nhờ đó O đạt 8 electron và mỗi H đạt 2 electron ở lớp ngoài cùng.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Liên kết cho - nhận là loại liên kết cộng hoá trị đặc biệt, trong đó","o":["cặp electron dùng chung được tạo thành từ hai ion trái dấu","liên kết chỉ hình thành giữa các nguyên tử kim loại","liên kết hình thành giữa các phân tử nước với nhau","cặp electron dùng chung do một nguyên tử đóng góp cả hai electron, nguyên tử còn lại chỉ nhận"],"a":"cặp electron dùng chung do một nguyên tử đóng góp cả hai electron, nguyên tử còn lại chỉ nhận","h":"Tên gọi 'cho - nhận' nói lên cách hình thành cặp electron dùng chung.","e":"Trong liên kết cho - nhận, cặp electron dùng chung do một nguyên tử 'cho' cả hai electron, nguyên tử kia 'nhận'. Ví dụ: trong ion NH4+, nguyên tử N của NH3 dùng cặp electron chưa liên kết để liên kết với H+.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"So với H2S, nước (H2O) có nhiệt độ sôi cao bất thường. Nguyên nhân chủ yếu là","o":["giữa các phân tử nước có liên kết hydrogen","phân tử nước nhẹ hơn phân tử H2S nên dễ sôi hơn","trong phân tử nước có liên kết ion","nước là hợp chất của kim loại với phi kim"],"a":"giữa các phân tử nước có liên kết hydrogen","h":"Nguyên tử H trong phân tử nước hút mạnh nguyên tử O của phân tử nước bên cạnh.","e":"Giữa các phân tử nước tồn tại liên kết hydrogen: nguyên tử H (liên kết với O) của phân tử này bị hút bởi nguyên tử O của phân tử khác. Muốn đun sôi nước phải tốn thêm năng lượng phá vỡ các liên kết này nên nhiệt độ sôi của nước cao bất thường (100 độ C).","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Tinh thể muối ăn (NaCl) không dẫn điện, nhưng NaCl nóng chảy hoặc dung dịch NaCl lại dẫn điện vì","o":["khi đó NaCl biến thành kim loại","khi nóng chảy hoặc tan trong nước, các ion Na+ và Cl- chuyển động tự do được","nhiệt độ cao làm xuất hiện electron tự do như trong kim loại","khi nóng chảy NaCl phân huỷ thành Na và Cl2"],"a":"khi nóng chảy hoặc tan trong nước, các ion Na+ và Cl- chuyển động tự do được","h":"Muốn dẫn điện cần có hạt mang điện chuyển động tự do.","e":"Ở dạng tinh thể, các ion Na+ và Cl- bị giữ cố định tại các nút mạng nên không dẫn điện. Khi nóng chảy hoặc hoà tan, các ion được giải phóng và chuyển động tự do, mang điện tích di chuyển nên dung dịch/nóng chảy dẫn điện.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Tương tác van der Waals là","o":["liên kết mạnh giữa các ion trong tinh thể","liên kết giữa các nguyên tử bên trong một phân tử","tương tác yếu giữa các phân tử, yếu hơn nhiều so với liên kết cộng hoá trị","lực hút giữa hạt nhân và electron trong nguyên tử"],"a":"tương tác yếu giữa các phân tử, yếu hơn nhiều so với liên kết cộng hoá trị","h":"Nhờ tương tác này mà các khí hiếm và phân tử không phân cực có thể hoá lỏng khi hạ nhiệt độ đủ thấp.","e":"Tương tác van der Waals là tương tác tĩnh điện yếu giữa các phân tử, sinh ra do sự phân bố electron không đều tạm thời. Nó yếu hơn nhiều so với liên kết ion và liên kết cộng hoá trị nhưng ảnh hưởng đến nhiệt độ nóng chảy, nhiệt độ sôi của các chất.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Số oxi hoá của nguyên tố trong đơn chất luôn bằng","o":["0","+1","-2","số hiệu nguyên tử của nguyên tố"],"a":"0","h":"Đây là quy tắc đầu tiên khi xác định số oxi hoá.","e":"Theo quy tắc, số oxi hoá của nguyên tố trong đơn chất luôn bằng 0, ví dụ: O2, Fe, Cl2, S đều có số oxi hoá 0.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong hợp chất H2SO4, số oxi hoá của lưu huỳnh (S) là","o":["+2","+4","-2","+6"],"a":"+6","h":"Tổng số oxi hoá của các nguyên tử trong phân tử trung hoà bằng 0; H thường là +1, O thường là -2.","e":"Gọi số oxi hoá của S là x: 2 x (+1) + x + 4 x (-2) = 0, suy ra x = +6.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Cho phản ứng: Zn + CuSO4 -> ZnSO4 + Cu. Chất khử trong phản ứng này là","o":["CuSO4","Zn","Cu","ZnSO4"],"a":"Zn","h":"Chất khử là chất nhường electron, số oxi hoá của nó tăng sau phản ứng.","e":"Zn có số oxi hoá tăng từ 0 lên +2 trong ZnSO4, tức Zn đã nhường electron (bị oxi hoá) nên Zn là chất khử. Ngược lại, Cu2+ nhận electron thành Cu nên CuSO4 là chất oxi hoá.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Chất oxi hoá là chất","o":["nhường electron cho chất khác","có số oxi hoá tăng sau phản ứng","nhận electron của chất khác","luôn luôn là kim loại"],"a":"nhận electron của chất khác","h":"Chất oxi hoá 'oxi hoá' chất khác bằng cách lấy electron của nó.","e":"Chất oxi hoá là chất nhận electron; sau phản ứng số oxi hoá của nó giảm. Còn chất khử là chất nhường electron, số oxi hoá tăng.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Phản ứng nào sau đây là phản ứng toả nhiệt?","o":["Đốt cháy củi, than để nấu ăn","Nung đá vôi ở nhiệt độ cao để sản xuất vôi sống","Quá trình quang hợp ở cây xanh","Phân huỷ KClO3 khi đun nóng liên tục"],"a":"Đốt cháy củi, than để nấu ăn","h":"Phản ứng toả nhiệt giải phóng nhiệt ra môi trường xung quanh.","e":"Sự cháy (củi, than, gas) là phản ứng toả nhiệt điển hình: vừa phát sáng vừa toả nhiều nhiệt. Nung đá vôi và quang hợp cần hấp thụ năng lượng nên là phản ứng thu nhiệt.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Biến thiên enthalpy của một phản ứng hoá học cho biết","o":["phản ứng diễn ra nhanh hay chậm","lượng nhiệt toả ra hay thu vào của phản ứng","số mol chất tham gia phản ứng","phản ứng có cần chất xúc tác hay không"],"a":"lượng nhiệt toả ra hay thu vào của phản ứng","h":"Enthalpy liên quan đến nhiệt của phản ứng, không liên quan đến tốc độ.","e":"Biến thiên enthalpy (kí hiệu delta H) cho biết lượng nhiệt mà phản ứng toả ra hay thu vào. Phản ứng toả nhiệt có delta H < 0, phản ứng thu nhiệt có delta H > 0.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Muốn tăng tốc độ phản ứng giữa đá vôi và dung dịch HCl, cách làm hiệu quả là","o":["dùng đá vôi dạng tảng lớn thay cho dạng bột","hạ thấp nhiệt độ của dung dịch","đập nhỏ đá vôi thành bột và dùng dung dịch HCl đậm đặc hơn","pha loãng dung dịch HCl bằng nhiều nước"],"a":"đập nhỏ đá vôi thành bột và dùng dung dịch HCl đậm đặc hơn","h":"Hãy nghĩ đến các yếu tố: diện tích tiếp xúc và nồng độ.","e":"Đập nhỏ đá vôi làm tăng diện tích tiếp xúc với axit; tăng nồng độ HCl làm các hạt va chạm hiệu quả thường xuyên hơn. Cả hai đều làm tốc độ phản ứng tăng. Giảm nhiệt độ, pha loãng hay dùng tảng lớn đều làm phản ứng chậm lại.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Các nguyên tố halogen thuộc nhóm nào trong bảng tuần hoàn?","o":["IA","IIA","VIA","VIIA"],"a":"VIIA","h":"Nguyên tử halogen có 7 electron ở lớp ngoài cùng.","e":"Nhóm halogen gồm F, Cl, Br, I thuộc nhóm VIIA. Nguyên tử của chúng có 7 electron lớp ngoài cùng, chỉ cần nhận thêm 1 electron là đạt cấu hình bền của khí hiếm nên tính oxi hoá mạnh.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Khí chlorine (Cl2) được dùng để khử trùng nước sinh hoạt vì chlorine","o":["có tính oxi hoá mạnh, diệt được vi khuẩn","có mùi thơm, dễ chịu","hoàn toàn không độc với mọi sinh vật","làm cho nước có màu xanh đẹp"],"a":"có tính oxi hoá mạnh, diệt được vi khuẩn","h":"Tính chất hoá học nổi bật nhất của chlorine là gì?","e":"Chlorine có tính oxi hoá mạnh nên diệt được vi sinh vật gây bệnh trong nước. Tuy nhiên chlorine cũng độc đối với người khi hít phải lượng lớn, vì vậy khi khử trùng nước phải dùng lượng rất nhỏ, đúng quy định an toàn.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Nước Javen dùng để tẩy trắng và sát trùng trong gia đình chứa chất nào sau đây?","o":["NaCl","HCl","NaOH","NaClO"],"a":"NaClO","h":"Nước Javen là dung dịch muối của một acid yếu có tính oxi hoá mạnh.","e":"Nước Javen chứa sodium hypochlorite (NaClO). Ion ClO- có tính oxi hoá mạnh nên nước Javen tẩy màu và sát trùng tốt; không được trộn nước Javen với chất tẩy rửa chứa acid vì có thể sinh khí Cl2 độc.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Để phòng bệnh bướu cổ do thiếu iodine, người ta thường bổ sung iodine vào","o":["đường ăn","dầu ăn","gạo","muối ăn (muối iot)"],"a":"muối ăn (muối iot)","h":"Đây là thực phẩm gia vị được dùng hằng ngày trong mọi bữa ăn.","e":"Iodine cần cho tuyến giáp hoạt động; thiếu iodine gây bướu cổ, nhất là ở vùng núi, vùng xa biển. Vì vậy muối ăn thường được trộn thêm hợp chất chứa iodine, gọi là muối iot.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Tốc độ phản ứng hoá học được xác định bằng đại lượng nào sau đây?","o":["Lượng nhiệt toả ra trong một đơn vị thời gian","Độ biến thiên nồng độ của một chất (chất phản ứng hoặc sản phẩm) trong một đơn vị thời gian","Tổng khối lượng các chất sản phẩm tạo thành","Thời gian cần thiết để phản ứng xảy ra hoàn toàn"],"a":"Độ biến thiên nồng độ của một chất (chất phản ứng hoặc sản phẩm) trong một đơn vị thời gian","h":"Tốc độ gắn với sự thay đổi nồng độ của chất theo thời gian.","e":"Tốc độ phản ứng được đo bằng độ biến thiên nồng độ của một chất phản ứng hoặc sản phẩm trong một đơn vị thời gian: nồng độ chất phản ứng giảm dần, nồng độ sản phẩm tăng dần theo thời gian.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Khi tăng nhiệt độ, tốc độ phản ứng hoá học tăng lên chủ yếu vì","o":["các hạt chất phản ứng chuyển động nhanh hơn nên va chạm mạnh và hiệu quả nhiều hơn","phản ứng tạo ra được nhiều sản phẩm hơn","nồng độ các chất phản ứng tự tăng lên","chất xúc tác được hình thành trong quá trình phản ứng"],"a":"các hạt chất phản ứng chuyển động nhanh hơn nên va chạm mạnh và hiệu quả nhiều hơn","h":"Nhiệt độ cao làm các hạt chất chuyển động thế nào so với khi lạnh?","e":"Nhiệt độ tăng làm các hạt chuyển động nhanh hơn, tần suất va chạm và số va chạm hiệu quả trong một đơn vị thời gian đều tăng, nên tốc độ phản ứng tăng.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Một viên thuốc sủi (dạng viên nén) được nghiền nhỏ trước khi thả vào nước sẽ tan và sủi bọt nhanh hơn viên nguyên vẹn. Nguyên nhân là","o":["nghiền nhỏ làm tăng nhiệt độ của nước","nghiền nhỏ làm thay đổi bản chất hoá học của thuốc","nghiền nhỏ làm tăng diện tích bề mặt tiếp xúc giữa thuốc và nước","nghiền nhỏ làm tăng khối lượng của thuốc"],"a":"nghiền nhỏ làm tăng diện tích bề mặt tiếp xúc giữa thuốc và nước","h":"Chất rắn càng nhỏ thì phần bề mặt tiếp xúc với chất lỏng càng lớn hay nhỏ?","e":"Nghiền nhỏ chất rắn làm tăng diện tích bề mặt tiếp xúc với chất lỏng, các hạt va chạm với nhau nhiều hơn nên phản ứng xảy ra nhanh hơn.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Chất xúc tác trong một phản ứng hoá học có vai trò gì?","o":["Làm tăng lượng sản phẩm thu được sau phản ứng","Bị tiêu hao dần trong quá trình phản ứng","Biến mọi phản ứng thành phản ứng toả nhiệt","Làm tăng tốc độ phản ứng và không bị biến đổi về chất sau phản ứng"],"a":"Làm tăng tốc độ phản ứng và không bị biến đổi về chất sau phản ứng","h":"Sau khi phản ứng kết thúc, chất xúc tác còn nguyên vẹn không?","e":"Chất xúc tác làm tăng tốc độ phản ứng nhưng bản thân nó không bị biến đổi về chất và lượng sau phản ứng, nên có thể thu hồi và dùng lại.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Xét các oxide cao nhất của các nguyên tố trong chu kì 3: Na2O, MgO, Al2O3, SiO2, P2O5, SO3, Cl2O7. Khi đi từ trái sang phải trong chu kì, tính chất của các oxide này biến đổi theo xu hướng nào?","o":["Từ tính acid chuyển dần sang tính base","Từ tính base chuyển dần sang lưỡng tính rồi tính acid","Tất cả đều là oxide lưỡng tính","Không theo quy luật biến đổi nào"],"a":"Từ tính base chuyển dần sang lưỡng tính rồi tính acid","h":"Na2O là oxide base, Al2O3 lưỡng tính, vậy SO3 thuộc loại oxide nào?","e":"Trong một chu kì, oxide cao nhất của các nguyên tố biến đổi tính chất từ base (Na2O, MgO) qua lưỡng tính (Al2O3) đến acid (SiO2, P2O5, SO3, Cl2O7), trong đó SO3 là một oxide acid điển hình.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về tính acid của các dung dịch hydrohalic acid HX (X là nguyên tố halogen)?","o":["HF là acid mạnh nhất, còn HCl là acid yếu","Tất cả các dung dịch HX đều là acid yếu","HCl là acid mạnh, còn HF là acid yếu","HBr là acid yếu, còn HF là acid mạnh"],"a":"HCl là acid mạnh, còn HF là acid yếu","h":"HF rất nguy hiểm khi tiếp xúc da nhưng lại phân li ra ion H+ rất ít trong nước.","e":"Dung dịch HCl (tương tự HBr, HI) là acid mạnh, phân li gần như hoàn toàn trong nước; riêng dung dịch HF là acid yếu, chỉ phân li một phần.","t":"hoa-lop10","g":10,"l":"thu-thach"},{"p":"Để nhận biết ion chloride trong dung dịch muối chloride, người ta nhỏ dung dịch silver nitrate (AgNO3) vào mẫu thử. Hiện tượng chứng tỏ có ion chloride là","o":["xuất hiện kết tủa trắng AgCl","dung dịch chuyển sang màu xanh lam","có khí không màu thoát ra","xuất hiện kết tủa màu vàng đậm"],"a":"xuất hiện kết tủa trắng AgCl","h":"Ion Ag+ kết hợp với ion chloride tạo thành một muối rất ít tan có màu đặc trưng.","e":"Ion Ag+ tác dụng với ion chloride tạo kết tủa trắng silver chloride (AgCl) không tan trong nước, ví dụ: AgNO3 + NaCl -> AgCl (kết tủa trắng) + NaNO3.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây là ĐÚNG và an toàn khi làm thí nghiệm hoá học?","o":["Đưa ống nghiệm chứa hoá chất lên sát mũi để ngửi trực tiếp","Nếm thử một ít hoá chất để nhận biết chất","Dùng miệng hút dung dịch bằng ống hút thuỷ tinh","Đeo kính bảo hộ, buộc tóc gọn gàng và khi cần ngửi thì dùng tay phẩy nhẹ hơi hoá chất về phía mũi"],"a":"Đeo kính bảo hộ, buộc tóc gọn gàng và khi cần ngửi thì dùng tay phẩy nhẹ hơi hoá chất về phía mũi","h":"Tuyệt đối không ngửi trực tiếp, không nếm hoá chất và không dùng miệng hút dung dịch.","e":"Trong phòng thí nghiệm phải đeo kính bảo hộ, buộc tóc gọn; khi cần nhận biết mùi hoá chất, dùng tay phẩy nhẹ hơi hoá chất về phía mũi chứ không ngửi trực tiếp, và tuyệt đối không nếm hay dùng miệng hút hoá chất.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Ý nghĩa quan trọng của bảng tuần hoàn các nguyên tố hoá học là: chỉ cần biết vị trí của một nguyên tố trong bảng tuần hoàn, người ta...","o":["Chỉ dùng để tra cứu khối lượng nguyên tử của các nguyên tố","Có thể suy đoán được cấu tạo nguyên tử, tính chất của nguyên tố và hợp chất của nó, kể cả với nguyên tố chưa tìm thấy","Chỉ có ý nghĩa lịch sử, không còn dùng trong nghiên cứu hiện nay","Cho biết chính xác ngày tháng một nguyên tố được phát hiện"],"a":"Có thể suy đoán được cấu tạo nguyên tử, tính chất của nguyên tố và hợp chất của nó, kể cả với nguyên tố chưa tìm thấy","h":"Hãy nhớ Mendeleev đã dự đoán tính chất của các nguyên tố chưa được phát hiện dựa vào bảng tuần hoàn.","e":"Bảng tuần hoàn là 'bản đồ' của hoá học: biết vị trí của một nguyên tố (ô, chu kì, nhóm), ta suy ra được số hiệu nguyên tử, cấu hình electron, tính kim loại hay phi kim, hoá trị trong hợp chất với oxygen. Nhờ đó, Mendeleev từng dự đoán đúng tính chất của một số nguyên tố khi chúng chưa được phát hiện.","t":"hoa-lop10","g":10,"l":"nhe-nhang"},{"p":"Phản ứng thuận nghịch là phản ứng như thế nào?","o":["Xảy ra đồng thời theo hai chiều ngược nhau trong cùng một điều kiện","Chỉ xảy ra theo một chiều duy nhất cho đến khi hết hẳn chất phản ứng","Luôn xảy ra rất chậm và không toả nhiệt hay thu nhiệt","Chỉ xảy ra được khi có mặt chất xúc tác"],"a":"Xảy ra đồng thời theo hai chiều ngược nhau trong cùng một điều kiện","h":"Phản ứng này được viết bằng mũi tên hai chiều ⇌ trong phương trình hoá học.","e":"Phản ứng thuận nghịch xảy ra đồng thời theo hai chiều ngược nhau trong cùng một điều kiện: chất phản ứng tạo thành sản phẩm (chiều thuận), đồng thời sản phẩm lại tác dụng với nhau tạo lại chất đầu (chiều nghịch).","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Khi một phản ứng thuận nghịch đạt trạng thái cân bằng hoá học, điều nào sau đây là đúng?","o":["Phản ứng thuận và phản ứng nghịch đều đã dừng hẳn","Tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch","Nồng độ các chất phản ứng luôn bằng nồng độ các chất sản phẩm","Trong hệ không còn chất phản ứng nào nữa"],"a":"Tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch","h":"Cân bằng hoá học là cân bằng động, không phải cân bằng tĩnh.","e":"Ở trạng thái cân bằng, phản ứng thuận và phản ứng nghịch vẫn diễn ra nhưng với tốc độ bằng nhau nên nồng độ các chất không thay đổi theo thời gian. Vì vậy cân bằng hoá học là cân bằng động.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Cho cân bằng: N2(k) + 3H2(k) ⇌ 2NH3(k). Khi tăng áp suất của hệ, cân bằng chuyển dịch theo chiều nào?","o":["Theo chiều nghịch, tạo thành N2 và H2","Không chuyển dịch vì áp suất không ảnh hưởng","Theo chiều thuận, tạo thành NH3","Chuyển dịch luân phiên giữa hai chiều"],"a":"Theo chiều thuận, tạo thành NH3","h":"Tăng áp suất, cân bằng chuyển dịch theo chiều làm giảm số mol khí. Hãy đếm số mol khí ở hai vế.","e":"Vế trái có 1 + 3 = 4 mol khí, vế phải có 2 mol khí. Theo nguyên lí Le Chatelier, tăng áp suất làm cân bằng chuyển dịch theo chiều giảm số mol khí, tức chiều thuận tạo thành NH3.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Theo nguyên lí Le Chatelier, khi ta tăng nồng độ một chất trong hệ đang ở trạng thái cân bằng thì cân bằng sẽ chuyển dịch như thế nào?","o":["Không thay đổi gì vì hệ đã cân bằng","Theo chiều làm tăng thêm nồng độ của chất đó","Dừng hẳn cả hai chiều phản ứng","Theo chiều làm giảm nồng độ của chất đó"],"a":"Theo chiều làm giảm nồng độ của chất đó","h":"Hệ cân bằng luôn 'chống lại' sự thay đổi tác động từ bên ngoài.","e":"Nguyên lí Le Chatelier: khi tác động một yếu tố bên ngoài vào hệ đang cân bằng, cân bằng chuyển dịch theo chiều chống lại sự tác động đó. Tăng nồng độ một chất thì cân bằng chuyển dịch theo chiều tiêu thụ (làm giảm nồng độ) chất đó.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Hằng số cân bằng Kc của một phản ứng thuận nghịch (ở điều kiện xác định) chỉ phụ thuộc vào yếu tố nào sau đây?","o":["Nhiệt độ","Nồng độ ban đầu của các chất","Áp suất của hệ","Sự có mặt của chất xúc tác"],"a":"Nhiệt độ","h":"Chất xúc tác chỉ làm cân bằng đến nhanh hơn, không làm thay đổi hằng số cân bằng.","e":"Hằng số cân bằng Kc chỉ phụ thuộc vào bản chất phản ứng và nhiệt độ. Thay đổi nồng độ, áp suất hay thêm chất xúc tác chỉ làm cân bằng chuyển dịch (hoặc đến nhanh hơn), không làm thay đổi giá trị Kc tại một nhiệt độ cho trước.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Trong công nghiệp, ammonia được tổng hợp theo phản ứng N2 + 3H2 ⇌ 2NH3. Điều kiện nào sau đây được áp dụng để quá trình đạt hiệu quả hợp lí?","o":["Áp suất thấp, nhiệt độ càng cao càng tốt, không cần xúc tác","Áp suất cao (khoảng 200 atm), nhiệt độ khoảng 450–500 °C, xúc tác sắt (Fe)","Áp suất thường, nhiệt độ phòng, xúc tác men sinh học","Áp suất rất thấp và nhiệt độ dưới 0 °C"],"a":"Áp suất cao (khoảng 200 atm), nhiệt độ khoảng 450–500 °C, xúc tác sắt (Fe)","h":"Nhớ quy trình Haber trong sản xuất phân đạm.","e":"Tổng hợp ammonia trong công nghiệp (quy trình Haber) dùng áp suất cao để cân bằng chuyển dịch sang chiều tạo NH3, nhiệt độ vừa phải 450–500 °C (đủ nhanh mà hiệu suất còn chấp nhận được) và chất xúc tác sắt để tăng tốc độ phản ứng.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Sự điện li là quá trình nào sau đây?","o":["Quá trình phân huỷ một chất thành các nguyên tử riêng lẻ","Quá trình chất tan bị oxi hoá bởi dung môi","Quá trình phân li các chất thành ion khi tan trong nước hoặc khi nóng chảy","Quá trình trung hoà acid bằng base trong dung dịch"],"a":"Quá trình phân li các chất thành ion khi tan trong nước hoặc khi nóng chảy","h":"Nhờ quá trình này mà dung dịch muối, acid, base dẫn được điện.","e":"Sự điện li là quá trình phân li các chất thành các ion (cation và anion) khi tan trong nước hoặc ở trạng thái nóng chảy. Các ion chuyển động tự do làm dung dịch (hoặc chất nóng chảy) dẫn điện.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Dãy nào sau đây gồm toàn các chất điện li mạnh?","o":["CH3COOH, NH3, H2CO3","NaCl, CH3COOH, NH3","H2S, CH3COOH, HF","HCl, NaOH, KNO3"],"a":"HCl, NaOH, KNO3","h":"Chất điện li mạnh phân li gần như hoàn toàn thành ion: acid mạnh, base mạnh và hầu hết các muối tan.","e":"HCl (acid mạnh), NaOH (base mạnh) và KNO3 (muối tan) đều phân li hoàn toàn thành ion trong nước nên là chất điện li mạnh. CH3COOH, NH3, H2CO3, H2S, HF là các chất điện li yếu, chỉ phân li một phần.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Theo thuyết Brønsted – Lowry, acid là chất có khả năng nào sau đây?","o":["Cho proton (H+)","Nhận proton (H+)","Cho cặp electron dùng chung","Nhận electron trong phản ứng"],"a":"Cho proton (H+)","h":"Trong thuyết này, base là chất nhận proton — acid thì ngược lại.","e":"Theo thuyết Brønsted – Lowry: acid là chất cho proton (H+), base là chất nhận proton (H+). Ví dụ: HCl + H2O → H3O+ + Cl−, trong đó HCl cho proton nên là acid, H2O nhận proton nên là base.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Chất lưỡng tính là chất vừa tác dụng được với dung dịch acid, vừa tác dụng được với dung dịch base. Chất nào sau đây là chất lưỡng tính?","o":["NaOH","Al(OH)3","HCl","NaCl"],"a":"Al(OH)3","h":"Một hydroxide của kim loại lưỡng tính rất quen thuộc trong chương trình: nhôm.","e":"Al(OH)3 là hydroxide lưỡng tính: tác dụng với acid (ví dụ HCl) tạo muối và nước, đồng thời cũng tác dụng với base mạnh (ví dụ NaOH) tạo muối aluminat và nước. NaOH chỉ có tính base, HCl chỉ có tính acid, NaCl là muối trung tính thông thường.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Một dung dịch có nồng độ ion H+ là [H+] = 10^-3 mol/L. Giá trị pH của dung dịch đó bằng bao nhiêu?","o":["1","2","3","11"],"a":"3","h":"pH = −lg[H+]. Với [H+] = 10^-3 thì −lg(10^-3) = 3.","e":"pH = −lg[H+] = −lg(10^-3) = 3. Dung dịch có pH = 3 < 7 nên có môi trường acid.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Nhỏ vài giọt phenolphtalein vào dung dịch sodium hydroxide (NaOH), dung dịch sẽ chuyển sang màu gì?","o":["Xanh dương","Vàng","Cam","Hồng"],"a":"Hồng","h":"Phenolphtalein không màu trong môi trường acid nhưng đổi màu rõ rệt trong môi trường base.","e":"Phenolphtalein là chất chỉ thị acid – base: không màu trong môi trường acid và trung tính, chuyển sang màu hồng trong môi trường base như dung dịch NaOH. Còn quỳ tím chuyển sang màu xanh trong môi trường base.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Trong giờ thực hành, một bạn bị dung dịch acid đậm đặc văng dính vào da tay. Việc cần làm ngay lập tức là gì?","o":["Rửa ngay vùng da đó dưới vòi nước sạch nhiều lần, rồi báo cho giáo viên","Bôi ngay dung dịch base đậm đặc lên để trung hoà acid","Chờ cho acid tự bay hơi hết rồi mới xử lí","Dùng khăn khô chà xát thật mạnh để lau sạch acid"],"a":"Rửa ngay vùng da đó dưới vòi nước sạch nhiều lần, rồi báo cho giáo viên","h":"Nguyên tắc sơ cứu hoá chất: pha loãng và loại bỏ hoá chất bằng nước sạch càng sớm càng tốt.","e":"Khi acid dính vào da, phải rửa ngay dưới vòi nước sạch chảy liên tục nhiều lần để pha loãng và cuốn trôi acid, sau đó báo giáo viên để được xử lí tiếp. Tuyệt đối không bôi base đậm đặc lên da vì phản ứng trung hoà toả nhiệt và base cũng gây bỏng.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Khí nitrogen (N2) chiếm khoảng bao nhiêu phần trăm thể tích không khí và được ứng dụng như thế nào?","o":["Khoảng 21%, chủ yếu dùng cho sự hô hấp","Khoảng 78%, dùng tạo môi trường trơ để bảo quản thực phẩm, linh kiện điện tử","Khoảng 50%, dùng làm nhiên liệu đốt","Khoảng 0,03%, dùng trong sản xuất nước ngọt có gas"],"a":"Khoảng 78%, dùng tạo môi trường trơ để bảo quản thực phẩm, linh kiện điện tử","h":"Khí chiếm phần lớn nhất trong không khí nhưng khá trơ về mặt hoá học.","e":"Nitrogen chiếm khoảng 78% thể tích không khí. Vì N2 khá trơ ở điều kiện thường nên được dùng tạo môi trường trơ: bơm vào túi đựng thực phẩm để bảo quản, bảo vệ linh kiện điện tử, và nitrogen lỏng dùng làm lạnh sâu.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về ammonia (NH3)?","o":["Là chất khí không mùi, hầu như không tan trong nước","Là chất lỏng sánh như dầu, có tính acid mạnh","Là chất khí có mùi khai, tan rất nhiều trong nước; dung dịch NH3 có tính base yếu","Là chất rắn màu trắng, dùng trực tiếp làm phân bón dạng hạt"],"a":"Là chất khí có mùi khai, tan rất nhiều trong nước; dung dịch NH3 có tính base yếu","h":"Mùi khai quen thuộc ở nơi vệ sinh kém chính là mùi của khí này.","e":"Ammonia là chất khí không màu, có mùi khai đặc trưng, nhẹ hơn không khí và tan rất nhiều trong nước. Dung dịch NH3 có tính base yếu (làm quỳ tím hoá xanh), được dùng nhiều trong sản xuất phân đạm.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Để nhận biết một muối ammonium (chẳng hạn NH4Cl), người ta đun nóng nhẹ mẫu muối với dung dịch kiềm (NaOH). Hiện tượng nào chứng tỏ đó là muối ammonium?","o":["Xuất hiện kết tủa trắng không tan","Thoát ra khí không mùi, làm đục nước vôi trong","Thoát ra khí màu nâu đỏ có mùi hắc","Thoát ra khí có mùi khai, làm xanh giấy quỳ tím ẩm"],"a":"Thoát ra khí có mùi khai, làm xanh giấy quỳ tím ẩm","h":"Ion NH4+ gặp OH− sẽ giải phóng khí NH3.","e":"Muối ammonium tác dụng với dung dịch kiềm khi đun nóng nhẹ sẽ giải phóng khí ammonia: NH4Cl + NaOH → NaCl + NH3↑ + H2O. Khí NH3 có mùi khai và làm giấy quỳ tím ẩm chuyển xanh — đây là phản ứng nhận biết ion ammonium.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Nitric acid (HNO3) đặc nổi bật với tính chất nào sau đây mà khi sử dụng cần đặc biệt cẩn thận?","o":["Tính oxi hoá rất mạnh: tác dụng được với hầu hết kim loại (trừ Au, Pt) và gây bỏng nặng khi tiếp xúc với da","Tính khử rất mạnh, dễ bắt lửa khi gặp không khí","Hầu như không tác dụng với kim loại nào","Chỉ là một acid yếu, tương tự như acid trong giấm ăn"],"a":"Tính oxi hoá rất mạnh: tác dụng được với hầu hết kim loại (trừ Au, Pt) và gây bỏng nặng khi tiếp xúc với da","h":"Nhờ tính chất này mà HNO3 đặc hoà tan được cả đồng — kim loại không tan trong HCl loãng.","e":"HNO3 đặc là acid có tính oxi hoá rất mạnh: oxi hoá được hầu hết kim loại (trừ Au, Pt) và nhiều phi kim, đồng thời phá huỷ chất hữu cơ nên gây bỏng nặng. Khi làm việc với HNO3 đặc phải đeo găng tay, kính bảo hộ và thao tác cẩn thận.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Khí sulfur dioxide (SO2) sinh ra khi đốt nhiên liệu hoá thạch chứa sulfur là một trong những nguyên nhân chính gây ra hiện tượng môi trường nào?","o":["Thủng tầng ozone","Mưa acid","Thuỷ triều đỏ","Sa mạc hoá đất đai"],"a":"Mưa acid","h":"SO2 tan trong nước mưa tạo thành các acid yếu, làm nước mưa có pH thấp bất thường.","e":"SO2 thải vào khí quyển sẽ bị oxi hoá và hoà tan trong nước mưa tạo thành sulfuric acid loãng, gây mưa acid. Mưa acid làm hại cây trồng, ăn mòn công trình đá vôi, kim loại và làm chua đất, nước ao hồ.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Sulfuric acid (H2SO4) đặc rất háo nước. Cách pha loãng H2SO4 đặc an toàn và đúng kĩ thuật là:","o":["Rót nhanh nước vào acid đặc rồi khuấy mạnh","Rót acid đặc và nước vào cốc cùng một lúc","Rót từ từ acid đặc vào nước, vừa rót vừa khuấy đều","Đun nóng acid đặc lên rồi mới cho nước vào"],"a":"Rót từ từ acid đặc vào nước, vừa rót vừa khuấy đều","h":"Nhớ câu nhắc kinh điển trong phòng thí nghiệm: 'rót acid vào nước', tuyệt đối không làm ngược lại.","e":"H2SO4 đặc háo nước mạnh, quá trình pha loãng toả rất nhiều nhiệt. Phải rót từ từ acid đặc vào nước và khuấy đều để nhiệt phân tán. Nếu rót nước vào acid, nước nhẹ nổi lên trên, sôi đột ngột làm bắn acid đặc ra ngoài gây bỏng nguy hiểm.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Hợp chất hữu cơ là hợp chất của carbon. Trong thành phần của các hợp chất hữu cơ, hai nguyên tố hầu như luôn có mặt là:","o":["Carbon và oxygen","Hydrogen và oxygen","Carbon và các kim loại","Carbon và hydrogen (ngoài ra thường gặp oxygen, nitrogen, halogen...)"],"a":"Carbon và hydrogen (ngoài ra thường gặp oxygen, nitrogen, halogen...)","h":"Tên gọi 'hydrocarbon' bắt nguồn từ chính hai nguyên tố này.","e":"Hợp chất hữu cơ luôn chứa carbon và hầu như luôn chứa hydrogen; ngoài ra thường gặp oxygen, nitrogen, sulfur, halogen... Các hợp chất chỉ gồm carbon và hydrogen được gọi là hydrocarbon.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Công thức đơn giản nhất của một hợp chất hữu cơ cho ta biết điều gì?","o":["Tỉ lệ tối giản về số nguyên tử của các nguyên tố trong phân tử","Số nguyên tử chính xác của từng nguyên tố trong một phân tử","Khối lượng mol chính xác của hợp chất","Thứ tự liên kết giữa các nguyên tử trong phân tử"],"a":"Tỉ lệ tối giản về số nguyên tử của các nguyên tố trong phân tử","h":"Ví dụ: glucose C6H12O6 có công thức đơn giản nhất là CH2O.","e":"Công thức đơn giản nhất cho biết tỉ lệ số nguyên tử tối giản của các nguyên tố trong phân tử. Muốn xác định công thức phân tử (số nguyên tử chính xác) cần biết thêm khối lượng mol của chất: công thức phân tử là bội số nguyên lần của công thức đơn giản nhất.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Phát biểu nào sau đây phân biệt đúng 'đồng đẳng' và 'đồng phân' trong hoá học hữu cơ?","o":["Đồng đẳng là các chất có cùng công thức phân tử; đồng phân là các chất hơn kém nhau một nhóm CH2","Đồng đẳng là các chất có cấu tạo và tính chất tương tự, phân tử hơn kém nhau một hay nhiều nhóm CH2; đồng phân là các chất có cùng công thức phân tử nhưng cấu tạo khác nhau","Đồng đẳng và đồng phân đều là các chất có cùng công thức phân tử và cùng cấu tạo","Đồng phân là các chất có cùng cấu tạo nhưng công thức phân tử khác nhau"],"a":"Đồng đẳng là các chất có cấu tạo và tính chất tương tự, phân tử hơn kém nhau một hay nhiều nhóm CH2; đồng phân là các chất có cùng công thức phân tử nhưng cấu tạo khác nhau","h":"CH4, C2H6, C3H8 là dãy đồng đẳng; còn C2H6O có tới hai chất khác nhau (ethanol và dimethyl ether) — đó là đồng phân.","e":"Các chất đồng đẳng có cấu tạo và tính chất hoá học tương tự, phân tử hơn kém nhau một hay nhiều nhóm CH2 (ví dụ dãy alkane CH4, C2H6, C3H8...). Các chất đồng phân có cùng công thức phân tử nhưng khác nhau về cấu tạo nên tính chất khác nhau.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Methane (CH4) — thành phần chính của khí thiên nhiên — cháy hoàn toàn trong không khí tạo thành:","o":["CO và H2","C và H2O","CO2 và H2O","CH3OH và H2"],"a":"CO2 và H2O","h":"Mọi hydrocarbon cháy hoàn toàn đều cho cùng hai sản phẩm quen thuộc này.","e":"Methane cháy hoàn toàn theo phương trình: CH4 + 2O2 → CO2 + 2H2O, toả nhiều nhiệt nên methane được dùng làm nhiên liệu (khí thiên nhiên, khí biogas).","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Khi chiếu sáng hỗn hợp methane và chlorine (Cl2), phản ứng xảy ra thuộc loại nào?","o":["Phản ứng cộng vào liên kết đôi","Phản ứng trùng hợp tạo polymer","Phản ứng oxi hoá hoàn toàn (cháy)","Phản ứng thế: các nguyên tử H trong CH4 lần lượt bị thay thế bởi nguyên tử Cl"],"a":"Phản ứng thế: các nguyên tử H trong CH4 lần lượt bị thay thế bởi nguyên tử Cl","h":"Đây là phản ứng đặc trưng của alkane — phân tử đã bão hoà nên không cộng mà...?","e":"Alkane như methane có phản ứng đặc trưng là phản ứng thế: dưới tác dụng của ánh sáng, các nguyên tử hydrogen trong CH4 lần lượt bị thay thế bởi chlorine, tạo CH3Cl, CH2Cl2, CHCl3, CCl4 và HCl.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Dẫn khí ethylene (C2H4) vào dung dịch brom (nước brom màu da cam), dung dịch bị mất màu. Đó là do ethylene đã xảy ra:","o":["Phản ứng cộng với Br2 tại liên kết đôi C=C","Phản ứng thế với Br2 khi có ánh sáng","Phản ứng cháy với oxygen trong dung dịch","Phản ứng trùng hợp tạo thành nhựa"],"a":"Phản ứng cộng với Br2 tại liên kết đôi C=C","h":"Liên kết đôi C=C kém bền, dễ bị bẻ gãy để cộng thêm tác nhân — đây cũng là phản ứng nhận biết alkene.","e":"Ethylene có liên kết đôi C=C nên dễ tham gia phản ứng cộng: C2H4 + Br2 → C2H4Br2. Sản phẩm không màu nên nước brom mất màu da cam — đây là phản ứng dùng để nhận biết alkene.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Nhựa polyethylene (PE) — nguyên liệu làm túi nilon, chai lọ, ống nhựa — được sản xuất từ ethylene bằng phản ứng nào?","o":["Phản ứng cộng với HCl","Phản ứng trùng hợp","Phản ứng thế với chlorine","Phản ứng tách nước"],"a":"Phản ứng trùng hợp","h":"Hàng nghìn phân tử ethylene nhỏ nối lại với nhau thành một phân tử khổng lồ.","e":"Ở nhiệt độ, áp suất và xúc tác thích hợp, nhiều phân tử ethylene liên kết với nhau thành phân tử dài polyethylene (PE) — đó là phản ứng trùng hợp. PE bền, nhẹ, cách điện nên được dùng rộng rãi làm túi, chai lọ, ống dẫn.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong sản xuất nông nghiệp, khí ethylene còn được sử dụng dựa trên tác dụng sinh lí nào sau đây?","o":["Làm lạnh để bảo quản nông sản lâu dài","Khử trùng đất trước khi gieo trồng","Kích thích quả mau chín (ethylene là một hormone thực vật)","Diệt cỏ dại trên ruộng"],"a":"Kích thích quả mau chín (ethylene là một hormone thực vật)","h":"Người ta thường úm chuối, xoài xanh chung với một ít quả đã chín vì quả chín tự thoát ra khí này.","e":"Ethylene là hormone thực vật có tác dụng kích thích quá trình chín của quả. Trong thực tế, người ta dùng ethylene (hoặc các chất sinh ethylene) để úm cho chuối, xoài, cà chua... chín đều và đúng thời điểm thu hoạch, vận chuyển.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Acetylene (C2H2) cháy trong oxygen toả ra lượng nhiệt rất lớn, ngọn lửa có thể đạt khoảng 3000 °C. Nhờ đó acetylene được ứng dụng chủ yếu trong:","o":["Thắp sáng bằng đèn dầu","Bếp gas đun nấu gia đình","Nhà máy nhiệt điện","Đèn xì oxygen – acetylene để hàn và cắt kim loại"],"a":"Đèn xì oxygen – acetylene để hàn và cắt kim loại","h":"Người thợ cơ khí dùng thiết bị này để cắt các tấm thép dày.","e":"Ngọn lửa của acetylene cháy trong oxygen đạt nhiệt độ rất cao (khoảng 3000 °C), đủ làm nóng chảy kim loại, nên được dùng trong đèn xì để hàn và cắt kim loại. Acetylene thường được sinh ra từ calcium carbide (đất đèn) tác dụng với nước.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về benzene (C6H6) và việc sử dụng benzene an toàn?","o":["Phân tử benzene có cấu trúc vòng 6 cạnh; benzene rất độc, có thể gây ung thư nên phải tránh hít phải hơi và tiếp xúc lâu dài","Benzene là chất rắn màu trắng, hoàn toàn không độc hại","Benzene tan tốt trong nước và được dùng làm dung môi pha chế thực phẩm","Phân tử benzene có cấu trúc mạch thẳng gồm 6 nguyên tử carbon"],"a":"Phân tử benzene có cấu trúc vòng 6 cạnh; benzene rất độc, có thể gây ung thư nên phải tránh hít phải hơi và tiếp xúc lâu dài","h":"Benzene là đại diện tiêu biểu của dãy arene (hydrocarbon thơm) với vòng 6 cạnh đặc trưng.","e":"Benzene là hydrocarbon thuộc dãy arene, phân tử có cấu trúc vòng 6 cạnh phẳng với hệ liên kết đôi xen kẽ. Benzene là chất lỏng dễ bay hơi và rất độc (có thể gây ung thư máu), vì vậy trong công nghiệp và phòng thí nghiệm phải tránh hít hơi benzene và hạn chế tiếp xúc trực tiếp.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Ethanol (C2H5OH) — thành phần chính của cồn và rượu bia — có tính chất nào sau đây?","o":["Không tan trong nước, nổi thành lớp riêng","Tan vô hạn trong nước, cháy được với ngọn lửa xanh mờ, toả nhiệt","Là chất khí ở điều kiện thường, mùi hắc rất mạnh","Không cháy và không tác dụng với bất kì chất nào"],"a":"Tan vô hạn trong nước, cháy được với ngọn lửa xanh mờ, toả nhiệt","h":"Cồn y tế 70° là dung dịch của ethanol trong nước — điều đó nói lên khả năng hoà tan của nó.","e":"Ethanol là chất lỏng không màu, tan vô hạn trong nước, dễ cháy với ngọn lửa xanh mờ và toả nhiệt (C2H5OH + 3O2 → 2CO2 + 3H2O). Ethanol được dùng làm nhiên liệu, dung môi, sản xuất cồn sát trùng và đồ uống có cồn.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Vì sao người đã uống rượu bia tuyệt đối không được điều khiển phương tiện giao thông?","o":["Vì ethanol trong rượu bia làm tăng phản xạ quá mức gây nguy hiểm","Vì rượu bia chỉ bị cấm theo quy định chứ không ảnh hưởng gì tới sức khoẻ","Vì ethanol làm giảm khả năng tập trung, phán đoán và phản xạ chậm, dễ gây tai nạn; lạm dụng còn gây hại gan, thần kinh","Vì rượu bia giúp người lái tỉnh táo hơn nên dễ chủ quan"],"a":"Vì ethanol làm giảm khả năng tập trung, phán đoán và phản xạ chậm, dễ gây tai nạn; lạm dụng còn gây hại gan, thần kinh","h":"Hãy nghĩ tới tác động của ethanol lên hệ thần kinh trung ương.","e":"Ethanol ức chế hệ thần kinh trung ương: người uống rượu bia bị giảm tập trung, phán đoán kém, phản xạ chậm nên rất dễ gây tai nạn giao thông. Lạm dụng rượu bia lâu dài còn gây xơ gan, tổn thương thần kinh và nhiều bệnh khác — 'đã uống rượu bia thì không lái xe'.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Phenol và ethanol đều có nhóm –OH, nhưng phenol khác ethanol ở điểm cơ bản nào sau đây?","o":["Phenol không chứa nhóm –OH trong phân tử","Phenol tan vô hạn trong nước còn ethanol thì không tan","Ethanol có tính acid mạnh hơn phenol rất nhiều","Phenol có tính acid yếu (tác dụng được với dung dịch NaOH), còn ethanol thì không tác dụng với NaOH"],"a":"Phenol có tính acid yếu (tác dụng được với dung dịch NaOH), còn ethanol thì không tác dụng với NaOH","h":"Ở phenol, nhóm –OH gắn trực tiếp với vòng benzene nên tính chất thay đổi rõ rệt.","e":"Trong phenol, nhóm –OH liên kết trực tiếp với vòng benzene nên phenol có tính acid yếu: tác dụng được với dung dịch NaOH tạo sodium phenolate và nước. Ethanol là alcohol thông thường, không có tính acid này (không tác dụng với NaOH). Phenol cũng độc và gây bỏng da nên cần cẩn thận khi sử dụng.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Dung dịch formaldehyde (gọi là formalin) được dùng trong y học và sinh học chủ yếu để làm gì, và cần lưu ý điều gì?","o":["Bảo quản mẫu vật sinh học; formaldehyde rất độc nên phải tránh hít phải và tuyệt đối không dùng cho thực phẩm","Ướp thực phẩm để giữ tươi lâu vì formaldehyde an toàn với sức khoẻ","Pha vào nước uống để diệt khuẩn hằng ngày","Làm thuốc bổ sung dinh dưỡng cho người bệnh"],"a":"Bảo quản mẫu vật sinh học; formaldehyde rất độc nên phải tránh hít phải và tuyệt đối không dùng cho thực phẩm","h":"Các mẫu động vật ngâm trong lọ tại phòng thí nghiệm sinh học được giữ bằng dung dịch này.","e":"Formalin (dung dịch formaldehyde khoảng 37–40%) có khả năng diệt khuẩn và cố định protein nên được dùng bảo quản mẫu vật sinh học, khử trùng dụng cụ. Tuy nhiên formaldehyde rất độc, gây kích ứng mạnh và có thể gây ung thư — tuyệt đối không được dùng để bảo quản thực phẩm.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Giấm ăn dùng trong nấu nướng là dung dịch loãng (khoảng 2–5%) của chất nào sau đây?","o":["Hydrochloric acid (HCl)","Acetic acid (CH3COOH) — một acid hữu cơ yếu","Sulfuric acid (H2SO4)","Sodium hydroxide (NaOH)"],"a":"Acetic acid (CH3COOH) — một acid hữu cơ yếu","h":"Vị chua của giấm đến từ một carboxylic acid đơn giản nhất nhì trong dãy đồng đẳng.","e":"Giấm ăn là dung dịch acetic acid (CH3COOH) khoảng 2–5% trong nước. Acetic acid là carboxylic acid có tính acid yếu: làm quỳ tím chuyển đỏ nhạt, tác dụng với base và một số kim loại, đá vôi (tạo bọt khí CO2).","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Để nhận biết một aldehyde (có nhóm chức –CHO), người ta thường dùng phản ứng đặc trưng nào sau đây?","o":["Làm đổi màu giấy quỳ tím sang đỏ","Đốt cháy cho ngọn lửa xanh mờ","Phản ứng tráng bạc với thuốc thử Tollens, tạo lớp bạc sáng bám trên thành ống nghiệm","Tác dụng với sodium (Na) giải phóng khí hydrogen"],"a":"Phản ứng tráng bạc với thuốc thử Tollens, tạo lớp bạc sáng bám trên thành ống nghiệm","h":"Phản ứng này cũng là nguyên lí tráng gương, tráng ruột phích ngày xưa.","e":"Aldehyde có tính khử mạnh, khử được ion Ag+ trong thuốc thử Tollens thành bạc kim loại bám sáng như gương trên thành ống nghiệm — gọi là phản ứng tráng bạc. Đây là phản ứng đặc trưng để nhận biết nhóm chức aldehyde (–CHO).","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Phương pháp chưng cất dùng để tách và tinh chế chất lỏng (ví dụ tách rượu ethanol ra khỏi hỗn hợp rượu và nước) dựa trên cơ sở nào?","o":["Dựa vào sự khác nhau về độ tan trong nước của các chất","Dựa vào sự khác nhau về nhiệt độ sôi của các chất lỏng","Dựa vào sự khác nhau về màu sắc của các chất","Dựa vào khả năng bị nam châm hút của các chất"],"a":"Dựa vào sự khác nhau về nhiệt độ sôi của các chất lỏng","h":"Khi đun nóng hỗn hợp hai chất lỏng, chất nào sẽ bay hơi trước?","e":"Chưng cất dựa vào sự khác nhau về nhiệt độ sôi: chất có nhiệt độ sôi thấp hơn bay hơi trước, hơi được dẫn qua ống sinh hàn, ngưng tụ và thu riêng.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Để tinh chế một chất rắn hữu cơ bị lẫn tạp chất, người ta dùng phương pháp kết tinh lại. Phương pháp này dựa trên cơ sở nào?","o":["Sự khác nhau về độ tan của chất cần tinh chế và của tạp chất trong dung môi, độ tan thay đổi theo nhiệt độ","Sự khác nhau về nhiệt độ sôi của các chất rắn","Sự khác nhau về khối lượng riêng của các chất","Phản ứng hoá học xảy ra giữa tạp chất và dung môi"],"a":"Sự khác nhau về độ tan của chất cần tinh chế và của tạp chất trong dung môi, độ tan thay đổi theo nhiệt độ","h":"Hoà tan chất rắn trong dung môi nóng rồi để nguội dần thì điều gì xảy ra?","e":"Kết tinh lại dựa vào độ tan: chất cần tinh chế tan nhiều trong dung môi nóng, khi để nguội nó kết tinh tách ra dưới dạng tinh khiết hơn, còn tạp chất tan vẫn ở lại trong dung dịch.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Một hợp chất hữu cơ chỉ gồm C, H và O, có thành phần phần trăm khối lượng: 40% C, 6,7% H, còn lại là O. Công thức đơn giản nhất của hợp chất là","o":["CHO","C2H4O2","CH2O","CH4O"],"a":"CH2O","h":"Chia phần trăm khối lượng của mỗi nguyên tố cho nguyên tử khối của nó (C = 12, H = 1, O = 16) rồi rút gọn thành tỉ lệ số nguyên tối giản.","e":"Phần trăm O là 53,3%. Tỉ lệ mol nC : nH : nO = 40/12 : 6,7/1 : 53,3/16 = 3,33 : 6,7 : 3,33 = 1 : 2 : 1, vậy công thức đơn giản nhất là CH2O.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Theo thuyết cấu tạo hoá học, tính chất của một hợp chất hữu cơ phụ thuộc vào những yếu tố nào?","o":["Chỉ phụ thuộc vào thành phần nguyên tố của phân tử","Chỉ phụ thuộc vào trạng thái tồn tại (rắn, lỏng hay khí)","Chỉ phụ thuộc vào khối lượng phân tử của hợp chất","Phụ thuộc vào thành phần nguyên tố và cấu tạo hoá học, tức thứ tự liên kết giữa các nguyên tử trong phân tử"],"a":"Phụ thuộc vào thành phần nguyên tố và cấu tạo hoá học, tức thứ tự liên kết giữa các nguyên tử trong phân tử","h":"Vì sao các chất đồng phân có cùng công thức phân tử nhưng tính chất lại khác nhau?","e":"Theo thuyết cấu tạo hoá học, tính chất của hợp chất hữu cơ phụ thuộc vào thành phần và cấu tạo hoá học của phân tử. Các nguyên tử liên kết theo thứ tự khác nhau sẽ tạo thành các chất có tính chất khác nhau (hiện tượng đồng phân).","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Dẫn xuất halogen của hydrocarbon là hợp chất thu được khi","o":["thay thế một hay nhiều nguyên tử hydrogen trong phân tử hydrocarbon bằng nguyên tử halogen","cộng thêm phân tử halogen vào hydrocarbon","thay thế nguyên tử carbon trong hydrocarbon bằng nguyên tử halogen","hoà tan hydrocarbon trong dung dịch halogen"],"a":"thay thế một hay nhiều nguyên tử hydrogen trong phân tử hydrocarbon bằng nguyên tử halogen","h":"Chloroform CHCl3 được tạo thành từ methane khi lần lượt thay các nguyên tử H bằng nguyên tử Cl.","e":"Dẫn xuất halogen là sản phẩm thay thế một hay nhiều nguyên tử hydrogen của hydrocarbon bằng nguyên tử halogen (F, Cl, Br, I). Ví dụ: CHCl3 (chloroform) là dẫn xuất halogen của methane.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Nhiều dẫn xuất halogen (như các chất CFC) từng được dùng làm chất làm lạnh trong tủ lạnh, máy điều hoà. Ngày nay chúng bị hạn chế và tiến tới cấm sử dụng vì lí do nào?","o":["Chúng có giá thành quá rẻ nên gây lãng phí","Khả năng làm lạnh của chúng rất kém","Chúng phá huỷ tầng ozone và gây hại cho môi trường","Chúng làm thực phẩm trong tủ lạnh đóng băng quá nhanh"],"a":"Chúng phá huỷ tầng ozone và gây hại cho môi trường","h":"Tầng ozone ở tầng bình lưu có vai trò che chắn tia tử ngoại cho Trái Đất.","e":"Các chất CFC khi thải ra khí quyển sẽ phá huỷ tầng ozone, làm tia tử ngoại có hại lọt xuống Trái Đất. Ngoài ra, nhiều dẫn xuất halogen khó tan trong nước, khó phân huỷ nên tích luỹ và gây hại lâu dài cho môi trường.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Acetone (propanone) — chất lỏng quen thuộc trong nước tẩy sơn móng tay — thuộc loại hợp chất nào và được dùng chủ yếu với vai trò gì?","o":["Là một alcohol, dùng làm nhiên liệu đốt","Là một ketone, dùng làm dung môi hoà tan nhiều chất hữu cơ","Là một carboxylic acid, dùng làm giấm ăn","Là một ester, dùng làm hương liệu thực phẩm"],"a":"Là một ketone, dùng làm dung môi hoà tan nhiều chất hữu cơ","h":"Acetone có nhóm C=O liên kết với hai gốc hydrocarbon — đó là nhóm chức của ketone.","e":"Acetone (CH3COCH3) là ketone đơn giản nhất. Nó là dung môi tốt, hoà tan được sơn, nhựa, keo nên được dùng làm nước tẩy sơn móng tay và trong nhiều ngành công nghiệp.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Cho acetic acid (CH3COOH, thành phần chính của giấm ăn) tác dụng với kim loại zinc (Zn). Hiện tượng quan sát được là","o":["không có hiện tượng gì xảy ra","xuất hiện kết tủa trắng và không có khí thoát ra","có khí màu nâu đỏ thoát ra","kim loại tan dần, có bọt khí không màu là hydrogen (H2) thoát ra"],"a":"kim loại tan dần, có bọt khí không màu là hydrogen (H2) thoát ra","h":"Acid tác dụng với kim loại hoạt động đứng trước hydrogen trong dãy hoạt động hoá học thì tạo muối và giải phóng khí nào?","e":"Acetic acid thể hiện tính acid: tác dụng với các kim loại hoạt động như Zn, Mg, giải phóng khí hydrogen: 2CH3COOH + Zn -> (CH3COO)2Zn + H2.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Ở điều kiện thường, khí nitrogen (N2) khá trơ, khó tham gia phản ứng hoá học. Nguyên nhân chính là gì?","o":["Phân tử N2 có khối lượng rất nhẹ nên bay lên cao","Giữa hai nguyên tử nitrogen có liên kết ba rất bền, cần năng lượng lớn mới phá vỡ được","Nitrogen là khí hiếm thuộc nhóm VIIIA","Nitrogen không tan trong bất kì chất nào"],"a":"Giữa hai nguyên tử nitrogen có liên kết ba rất bền, cần năng lượng lớn mới phá vỡ được","h":"Hãy nhớ cấu tạo phân tử N2: hai nguyên tử N liên kết với nhau bằng mấy liên kết?","e":"Phân tử N2 gồm hai nguyên tử nitrogen liên kết với nhau bằng một liên kết ba (N≡N) rất bền vững. Vì vậy, ở điều kiện thường N2 hầu như không tham gia phản ứng hoá học (khí trơ tương đối), chỉ phản ứng ở nhiệt độ rất cao hoặc có xúc tác, tia lửa điện.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Khí nào sau đây có màu nâu đỏ, rất độc và là một trong những tác nhân góp phần gây mưa acid?","o":["Nitrogen dioxide (NO2)","Carbon dioxide (CO2)","Nitrogen (N2)","Sulfur dioxide (SO2)"],"a":"Nitrogen dioxide (NO2)","h":"Có một oxide của nitrogen nổi bật với màu nâu đỏ thường thấy trong khói thải xe cộ giờ cao điểm.","e":"NO2 là chất khí có màu nâu đỏ đặc trưng, rất độc. Cùng với SO2, các oxide của nitrogen (NOx) thải ra từ động cơ xe và nhà máy hoà tan trong hơi nước khí quyển tạo thành acid nitric, góp phần gây mưa acid.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Nhận định nào sau đây đúng về đơn chất sulfur (lưu huỳnh)?","o":["Chất rắn, màu vàng, khi cháy trong oxygen tạo thành khí sulfur dioxide có mùi hắc","Chất khí, không màu, không mùi ở điều kiện thường","Chất lỏng, màu đen, sánh như dầu mỏ","Chất rắn, màu trắng, tan tốt trong nước"],"a":"Chất rắn, màu vàng, khi cháy trong oxygen tạo thành khí sulfur dioxide có mùi hắc","h":"Hãy liên hệ màu sắc quen thuộc của bột lưu huỳnh và mùi khí sinh ra khi đốt diêm, pháo.","e":"Sulfur ở điều kiện thường là chất rắn màu vàng, không tan trong nước. Khi đốt cháy, sulfur tác dụng với oxygen tạo thành sulfur dioxide (SO2): S + O2 → SO2; khí SO2 không màu, có mùi hắc, gây ho và là tác nhân gây mưa acid.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Để nhận biết ion sulfate (SO4²⁻) trong một dung dịch, người ta thường dùng thuốc thử nào và dựa vào hiện tượng gì?","o":["Dung dịch bạc nitrate (AgNO3), vì tạo kết tủa trắng của barium sulfate","Dung dịch barium chloride (BaCl2), vì tạo thành kết tủa trắng barium sulfate (BaSO4) không tan trong acid","Giấy quỳ tím, vì dung dịch muối sulfate luôn làm quỳ hoá đỏ mạnh","Dung dịch phenolphtalein, vì dung dịch sẽ hoá hồng"],"a":"Dung dịch barium chloride (BaCl2), vì tạo thành kết tủa trắng barium sulfate (BaSO4) không tan trong acid","h":"Hãy nhớ phản ứng tạo kết tủa BaSO4 nổi tiếng trong nhận biết muối sulfate.","e":"Ion sulfate SO4²⁻ tác dụng với ion Ba²⁺ tạo thành kết tủa trắng BaSO4. Kết tủa này không tan trong dung dịch acid loãng, là dấu hiệu đặc trưng để nhận biết ion sulfate trong dung dịch.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Phương pháp chiết trong phòng thí nghiệm (dùng phễu chiết để tách hai chất lỏng không tan vào nhau) dựa trên cơ sở nào?","o":["Các chất có nhiệt độ sôi khác nhau","Các chất có độ tan khác nhau trong hai dung môi không trộn lẫn vào nhau (ví dụ nước và dầu), chất cần tách sẽ chuyển sang dung môi hoà tan nó tốt hơn","Các chất có kích thước hạt khác nhau","Các chất có màu sắc khác nhau"],"a":"Các chất có độ tan khác nhau trong hai dung môi không trộn lẫn vào nhau (ví dụ nước và dầu), chất cần tách sẽ chuyển sang dung môi hoà tan nó tốt hơn","h":"Hãy nghĩ đến phễu chiết tách dầu ăn ra khỏi nước.","e":"Chiết là phương pháp tách chất dựa trên sự phân bố khác nhau của chất tan giữa hai dung môi không trộn lẫn (như nước và một dung môi hữu cơ). Trong phòng thí nghiệm, người ta dùng phễu chiết; trong đời sống, ngâm dược liệu trong rượu để chiết xuất hoạt chất cũng là ứng dụng của phương pháp này.","t":"hoa-lop11","g":11,"l":"nhe-nhang"},{"p":"Một hợp chất hữu cơ có công thức đơn giản nhất là CH2O và có khối lượng mol phân tử bằng 60 g/mol. Công thức phân tử của hợp chất đó là:","o":["CH2O","C2H4O2","C3H6O3","C2H6O2"],"a":"C2H4O2","h":"Hãy tính khối lượng của một đơn vị CH2O rồi xem phân tử chứa mấy đơn vị như vậy.","e":"Khối lượng mol của một đơn vị CH2O là 12 + 2×1 + 16 = 30 g/mol. Số đơn vị trong phân tử: 60/30 = 2. Vậy công thức phân tử là (CH2O)2 = C2H4O2 (chính là acetic acid).","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Khi cho benzene tác dụng với bromine khan (có bột sắt làm xúc tác, đun nóng nhẹ), phản ứng xảy ra thuộc loại nào?","o":["Phản ứng cộng (bromine cộng vào nối đôi làm mất màu dung dịch bromine ngay lập tức)","Phản ứng thế (một nguyên tử hydrogen của benzene bị thay thế bởi một nguyên tử bromine)","Phản ứng cháy hoàn toàn","Không xảy ra phản ứng nào trong mọi điều kiện"],"a":"Phản ứng thế (một nguyên tử hydrogen của benzene bị thay thế bởi một nguyên tử bromine)","h":"Vòng benzene rất bền nên tính chất của nó khác hẳn các hydrocarbon không no mạch hở.","e":"Vòng benzene có cấu trúc bền vững đặc biệt nên benzene khó tham gia phản ứng cộng như alkene, mà ưu tiên phản ứng thế: với Br2 khan và xúc tác bột sắt (Fe), một nguyên tử hydrogen của benzene bị thay thế bởi một nguyên tử bromine, tạo thành bromobenzene.","t":"hoa-lop11","g":11,"l":"thu-thach"},{"p":"Ester là hợp chất hữu cơ được tạo thành khi nào?","o":["Khi thay thế nhóm -OH trong nhóm carboxyl (-COOH) của carboxylic acid bằng nhóm -OR'","Khi cho một alcohol tác dụng với một base mạnh","Khi đun nóng một carboxylic acid với kim loại","Khi cộng nước vào một alkene có xúc tác acid"],"a":"Khi thay thế nhóm -OH trong nhóm carboxyl (-COOH) của carboxylic acid bằng nhóm -OR'","h":"Nhớ cấu tạo của ester: R-COO-R'.","e":"Ester có công thức chung R-COO-R', được xem như sản phẩm thay thế nhóm -OH của nhóm -COOH trong phân tử carboxylic acid bằng nhóm -OR' của alcohol.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Để điều chế ethyl acetate từ acetic acid (CH3COOH) và ethanol (C2H5OH), điều kiện phản ứng ester hoá thường dùng là gì?","o":["Không cần xúc tác, phản ứng tự xảy ra nhanh ở nhiệt độ thường","Đun nóng với xúc tác H2SO4 đặc","Đun nóng với xúc tác NaOH","Cho qua xúc tác Ni ở áp suất cao"],"a":"Đun nóng với xúc tác H2SO4 đặc","h":"Phản ứng ester hoá là phản ứng thuận nghịch, cần acid mạnh làm xúc tác.","e":"CH3COOH + C2H5OH ⇌ CH3COOC2H5 + H2O. Phản ứng ester hoá xảy ra khi đun nóng với xúc tác H2SO4 đặc; H2SO4 đặc còn hút nước giúp cân bằng chuyển dịch theo chiều tạo ester.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi thuỷ phân một ester trong môi trường acid (đun nóng), sản phẩm thu được là gì?","o":["Muối của acid béo và glycerol","Khí CO2 và nước","Carboxylic acid và alcohol tương ứng","Một ester khác có phân tử khối lớn hơn"],"a":"Carboxylic acid và alcohol tương ứng","h":"Thuỷ phân trong môi trường acid là phản ứng nghịch của phản ứng ester hoá.","e":"Thuỷ phân ester trong môi trường acid là phản ứng thuận nghịch: R-COO-R' + H2O ⇌ R-COOH + R'-OH, tạo lại carboxylic acid và alcohol ban đầu.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Phản ứng xà phòng hoá là phản ứng nào sau đây?","o":["Phản ứng của ester với nước có xúc tác H2SO4 loãng","Phản ứng trùng hợp của các ester không no","Phản ứng của chất béo với dung dịch HCl đặc","Phản ứng thuỷ phân ester trong môi trường kiềm, tạo muối của carboxylic acid (với chất béo là muối của acid béo) và alcohol (glycerol)"],"a":"Phản ứng thuỷ phân ester trong môi trường kiềm, tạo muối của carboxylic acid (với chất béo là muối của acid béo) và alcohol (glycerol)","h":"Tên gọi của phản ứng gắn liền với sản phẩm quen thuộc dùng để giặt rửa.","e":"Xà phòng hoá là phản ứng thuỷ phân ester trong môi trường kiềm (NaOH, KOH), xảy ra một chiều. Với chất béo, sản phẩm là muối của acid béo (chính là xà phòng) và glycerol.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Một cơ sở sản xuất thủ công đun mỡ động vật với dung dịch NaOH, sau đó cho thêm dung dịch NaCl bão hoà vào hỗn hợp và thấy một lớp chất rắn màu trắng nổi lên trên. Lớp chất rắn đó là gì?","o":["Xà phòng (muối sodium của các acid béo), tách ra vì ít tan trong dung dịch NaCl bão hoà","Glycerol kết tinh lại ở nhiệt độ thường","Phần mỡ chưa phản ứng bị đông đặc","NaCl kết tinh do dung dịch đã bão hoà"],"a":"Xà phòng (muối sodium của các acid béo), tách ra vì ít tan trong dung dịch NaCl bão hoà","h":"Đây là bước 'tách xà phòng' quen thuộc trong quy trình nấu xà phòng thủ công.","e":"Đun chất béo với NaOH là phản ứng xà phòng hoá tạo xà phòng và glycerol tan trong hỗn hợp. Khi thêm NaCl bão hoà, xà phòng (muối sodium của acid béo) giảm độ tan nên tách ra thành lớp rắn nổi lên — người ta vớt lấy lớp này làm xà phòng.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Vì sao xà phòng giặt rửa kém hiệu quả trong nước cứng, trong khi chất giặt rửa tổng hợp vẫn dùng tốt?","o":["Nước cứng làm xà phòng bay hơi nhanh hơn","Các ion Ca2+ và Mg2+ trong nước cứng tác dụng với xà phòng tạo kết tủa (cặn) không tan, làm mất tác dụng tẩy rửa; chất giặt rửa tổng hợp không tạo kết tủa với các ion này","Nước cứng có pH quá cao làm hỏng sợi vải","Chất giặt rửa tổng hợp tan được trong dầu mỡ còn xà phòng thì không"],"a":"Các ion Ca2+ và Mg2+ trong nước cứng tác dụng với xà phòng tạo kết tủa (cặn) không tan, làm mất tác dụng tẩy rửa; chất giặt rửa tổng hợp không tạo kết tủa với các ion này","h":"Nước cứng chứa nhiều ion Ca2+ và Mg2+.","e":"Xà phòng là muối sodium/potassium của acid béo; gặp Ca2+, Mg2+ trong nước cứng sẽ tạo muối calcium, magnesium của acid béo kết tủa (váng cặn), vừa lãng phí xà phòng vừa bám bẩn lên vải. Chất giặt rửa tổng hợp được thiết kế để không tạo kết tủa với các ion này nên vẫn tẩy rửa tốt.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Nhận định nào sau đây về biodiesel là đúng?","o":["Biodiesel được chưng cất trực tiếp từ dầu mỏ giống như diesel thông thường","Biodiesel là dầu ăn nguyên chất đổ thẳng vào động cơ diesel","Biodiesel là hỗn hợp các ester (thường là methyl ester) của acid béo, sản xuất từ dầu thực vật hoặc mỡ động vật, là nhiên liệu tái tạo và cháy sạch hơn diesel từ dầu mỏ","Biodiesel không chứa carbon nên khi cháy không sinh ra khí CO2"],"a":"Biodiesel là hỗn hợp các ester (thường là methyl ester) của acid béo, sản xuất từ dầu thực vật hoặc mỡ động vật, là nhiên liệu tái tạo và cháy sạch hơn diesel từ dầu mỏ","h":"Biodiesel được tạo ra bằng phản ứng trao đổi ester giữa chất béo và methanol.","e":"Cho chất béo (dầu thực vật, mỡ động vật, kể cả dầu ăn đã qua sử dụng) phản ứng với methanol có xúc tác sẽ thu được methyl ester của các acid béo — chính là biodiesel — và glycerol. Đây là nhiên liệu có nguồn gốc sinh học, tái tạo được và ít khí thải độc hại hơn diesel dầu mỏ, tuy khi cháy vẫn sinh CO2.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Glucose (C6H12O6) gắn liền với vai trò nào trong cơ thể người?","o":["Là thành phần tạo nên thành tế bào thực vật","Là đường dự trữ trong gan dưới dạng tinh bột","Là chất tạo vị ngọt chính của đường mía","Là đường có trong máu ('đường huyết'), nguồn năng lượng trực tiếp cho tế bào"],"a":"Là đường có trong máu ('đường huyết'), nguồn năng lượng trực tiếp cho tế bào","h":"Khi xét nghiệm máu, chỉ số 'đường huyết' đo nồng độ của chất này.","e":"Glucose là monosaccharide có trong máu người với nồng độ khá ổn định (khoảng 0,1%), được tế bào sử dụng trực tiếp để tạo năng lượng. Glucose cũng có trong nhiều loại quả chín và mật ong.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Glucose có thể tham gia phản ứng tráng bạc (tráng gương) là nhờ đặc điểm cấu tạo nào?","o":["Phân tử glucose có nhóm aldehyde (-CHO) có tính khử","Phân tử glucose chứa nhiều nhóm -OH như alcohol đa chức","Glucose là đường đơn không bị thuỷ phân","Glucose có vị ngọt và tan tốt trong nước"],"a":"Phân tử glucose có nhóm aldehyde (-CHO) có tính khử","h":"Phản ứng tráng bạc cần một chất khử khử được ion Ag+ thành bạc kim loại.","e":"Trong dung dịch, glucose tồn tại một phần ở dạng mạch hở có nhóm -CHO. Nhóm aldehyde này khử ion Ag+ trong thuốc thử Tollens thành bạc kim loại bám lên thành ống nghiệm tạo lớp 'gương' bạc — đây cũng là phản ứng dùng để nhận biết glucose.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về fructose và saccharose?","o":["Fructose chỉ có trong mía, không có trong trái cây","Fructose có nhiều trong mật ong và trái cây chín; saccharose là đường ăn phổ biến, lấy chủ yếu từ mía và củ cải đường","Saccharose là monosaccharide đơn giản nhất","Fructose không có vị ngọt nên không dùng trong thực phẩm"],"a":"Fructose có nhiều trong mật ong và trái cây chín; saccharose là đường ăn phổ biến, lấy chủ yếu từ mía và củ cải đường","h":"Fructose còn được gọi là 'đường trái cây'.","e":"Fructose là monosaccharide có nhiều trong trái cây chín và mật ong (mật ong chứa khoảng 40% fructose), có vị ngọt đậm. Saccharose là disaccharide gồm một gốc glucose và một gốc fructose, chính là đường ăn chiết xuất từ mía và củ cải đường.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Nhỏ vài giọt dung dịch iodine lên một lát khoai tây sống, chỗ nhỏ iodine chuyển màu. Màu xuất hiện và kết luận đúng là gì?","o":["Màu đỏ gạch, chứng tỏ khoai tây chứa nhiều protein","Màu trắng đục, chứng tỏ khoai tây chứa chất béo","Màu xanh tím, chứng tỏ khoai tây chứa tinh bột","Màu vàng chanh, chứng tỏ khoai tây chứa glucose"],"a":"Màu xanh tím, chứng tỏ khoai tây chứa tinh bột","h":"Dung dịch iodine là thuốc thử đặc trưng của một carbohydrate dự trữ ở thực vật.","e":"Hồ tinh bột tác dụng với dung dịch iodine tạo màu xanh tím đặc trưng — đây là phản ứng dùng để nhận biết tinh bột. Khoai tây là củ giàu tinh bột nên hiện tượng này chứng tỏ trong khoai tây có tinh bột.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về cellulose?","o":["Cellulose là chất dự trữ năng lượng chính trong hạt ngũ cốc","Cellulose tan tốt trong nước nóng tạo hồ trong suốt","Dạ dày người tiêu hoá hoàn toàn cellulose thành glucose","Cellulose là thành phần chính của thành tế bào thực vật (có trong gỗ, bông); người không tiêu hoá được nhưng nó là chất xơ có lợi cho tiêu hoá"],"a":"Cellulose là thành phần chính của thành tế bào thực vật (có trong gỗ, bông); người không tiêu hoá được nhưng nó là chất xơ có lợi cho tiêu hoá","h":"Cơ thể người không có enzyme phân giải cellulose.","e":"Cellulose là polysaccharide tạo nên thành tế bào thực vật, là thành phần chính của gỗ, bông, sợi. Người không có enzyme cellulase nên không tiêu hoá được cellulose, nhưng cellulose đóng vai trò chất xơ giúp nhu động ruột tốt. Một số động vật ăn cỏ tiêu hoá được nhờ vi sinh vật trong dạ dày.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi nhai cơm thật kĩ và lâu, ta cảm thấy vị ngọt dần trong miệng. Giải thích đúng là gì?","o":["Enzyme amylase trong nước bọt thuỷ phân một phần tinh bột của cơm thành các đường (maltose, glucose) có vị ngọt","Tinh bột trong cơm phản ứng với không khí tạo thành đường","Cơm chứa sẵn rất nhiều glucose, nhai lâu glucose mới tan ra","Vị ngọt là do nước bọt tự có sẵn, không liên quan đến cơm"],"a":"Enzyme amylase trong nước bọt thuỷ phân một phần tinh bột của cơm thành các đường (maltose, glucose) có vị ngọt","h":"Quá trình tiêu hoá tinh bột bắt đầu ngay từ miệng nhờ enzyme.","e":"Nước bọt chứa enzyme amylase xúc tác thuỷ phân tinh bột thành maltose và một phần glucose — các đường này có vị ngọt nên nhai cơm lâu sẽ thấy ngọt. Đây là bước đầu của quá trình thuỷ phân tinh bột thành glucose để cơ thể hấp thu.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Amine là hợp chất hữu cơ có đặc điểm gì?","o":["Là hợp chất thu được khi thay thế nguyên tử H trong phân tử hydrocarbon bằng nhóm -COOH","Là hợp chất thu được khi thay thế một hay nhiều nguyên tử H trong phân tử NH3 (ammonia) bằng gốc hydrocarbon; amine có tính base yếu","Là muối tạo thành khi acid tác dụng với base","Là polymer sinh học cấu tạo từ các amino acid"],"a":"Là hợp chất thu được khi thay thế một hay nhiều nguyên tử H trong phân tử NH3 (ammonia) bằng gốc hydrocarbon; amine có tính base yếu","h":"Amine được xem là dẫn xuất của ammonia.","e":"Thay thế một, hai hoặc ba nguyên tử H trong phân tử NH3 bằng các gốc hydrocarbon ta được amine. Phân tử amine còn cặp electron tự do trên nguyên tử nitrogen nên có tính base yếu, tương tự ammonia.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về aniline (C6H5NH2)?","o":["Aniline là chất khí không màu, dùng làm nhiên liệu đốt","Aniline tan vô hạn trong nước tạo dung dịch có tính base mạnh","Aniline là chất lỏng, ít tan trong nước, là nguyên liệu quan trọng trong công nghiệp phẩm nhuộm","Aniline có tính acid mạnh như HCl"],"a":"Aniline là chất lỏng, ít tan trong nước, là nguyên liệu quan trọng trong công nghiệp phẩm nhuộm","h":"Aniline là amine thơm điển hình, gắn với lịch sử ngành nhuộm.","e":"Aniline là amine thơm, chất lỏng không màu (để lâu trong không khí chuyển nâu), ít tan trong nước và có tính base rất yếu. Aniline là nguyên liệu quan trọng để sản xuất phẩm nhuộm, dược phẩm và nhiều hoá chất khác.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Vì sao amino acid có tính lưỡng tính?","o":["Vì amino acid vừa tan trong nước vừa tan trong dầu","Vì amino acid vừa có tính oxi hoá vừa có tính khử","Vì amino acid chỉ chứa nhóm -NH2 nên tác dụng được với acid","Vì trong phân tử amino acid có cả nhóm -NH2 (có tính base) và nhóm -COOH (có tính acid), nên tác dụng được với cả acid và base"],"a":"Vì trong phân tử amino acid có cả nhóm -NH2 (có tính base) và nhóm -COOH (có tính acid), nên tác dụng được với cả acid và base","h":"Hãy nhìn vào hai nhóm chức cùng có mặt trong một phân tử amino acid.","e":"Amino acid có đồng thời nhóm amine -NH2 (tính base) và nhóm carboxyl -COOH (tính acid) trong cùng phân tử. Nhờ đó amino acid phản ứng được với cả dung dịch acid và dung dịch base — đó là tính lưỡng tính.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi hai phân tử amino acid liên kết với nhau tạo thành một dipeptide, phân tử nhỏ nào bị tách ra trong quá trình hình thành liên kết peptide?","o":["Một phân tử nước (H2O): nhóm -OH của nhóm -COOH và nguyên tử H của nhóm -NH2 tách ra, tạo liên kết -CO-NH-","Một phân tử CO2 do nhóm -COOH bị phân huỷ","Một phân tử NH3 do nhóm -NH2 bị tách ra","Một phân tử H2 do hai nguyên tử H kết hợp lại"],"a":"Một phân tử nước (H2O): nhóm -OH của nhóm -COOH và nguyên tử H của nhóm -NH2 tách ra, tạo liên kết -CO-NH-","h":"Liên kết peptide chính là liên kết -CO-NH- nối hai đơn vị amino acid.","e":"Nhóm -COOH của amino acid này kết hợp với nhóm -NH2 của amino acid kia: phần -OH và -H tách ra thành một phân tử H2O, phần còn lại nối với nhau bằng liên kết peptide -CO-NH-. Nhiều amino acid nối tiếp nhau theo cách này tạo thành chuỗi polypeptide và protein.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về protein?","o":["Protein là polymer được cấu tạo từ các monosaccharide như glucose","Protein là polymer sinh học cấu tạo từ các amino acid, giữ nhiều vai trò quan trọng: cấu tạo tế bào, xúc tác (enzyme), bảo vệ cơ thể (kháng thể)","Protein chính là chất béo dự trữ trong cơ thể động vật","Protein chỉ có trong thực vật, không có trong động vật"],"a":"Protein là polymer sinh học cấu tạo từ các amino acid, giữ nhiều vai trò quan trọng: cấu tạo tế bào, xúc tác (enzyme), bảo vệ cơ thể (kháng thể)","h":"Protein là một trong các chất hữu cơ cơ bản nhất của sự sống.","e":"Protein là hợp chất cao phân tử gồm nhiều đơn vị amino acid liên kết bằng liên kết peptide. Protein có mặt ở mọi tế bào và đảm nhiệm nhiều chức năng: cấu trúc, enzyme xúc tác, kháng thể bảo vệ, vận chuyển (như hemoglobin)...","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi làm sữa chua, sữa lỏng dần đông đặc lại thành khối mềm. Hiện tượng này và việc lòng trắng trứng đông lại khi luộc có cùng bản chất là gì?","o":["Vi khuẩn trong sữa chua đã ăn hết phần nước của sữa","Protein bị hoà tan hoàn toàn trong acid nên sữa đặc lại","Protein bị đông tụ (biến tính): acid lactic do vi khuẩn tạo ra làm protein của sữa đông tụ, giống như nhiệt độ cao làm protein lòng trắng trứng đông tụ khi luộc","Chất béo trong sữa kết tinh lại ở nhiệt độ thấp"],"a":"Protein bị đông tụ (biến tính): acid lactic do vi khuẩn tạo ra làm protein của sữa đông tụ, giống như nhiệt độ cao làm protein lòng trắng trứng đông tụ khi luộc","h":"Cả hai hiện tượng đều làm protein mất cấu trúc không gian và kết tụ lại.","e":"Protein dễ bị đông tụ (biến tính) khi đun nóng hoặc gặp acid, base, muối kim loại nặng. Làm sữa chua: vi khuẩn lactic lên men tạo acid lactic làm protein sữa đông tụ. Luộc trứng: nhiệt làm protein lòng trắng đông tụ thành khối trắng đục. Hai hiện tượng có cùng bản chất là sự đông tụ protein.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Enzyme là gì?","o":["Một loại acid mạnh trong dạ dày giúp phân huỷ mọi loại thức ăn","Một loại chất béo cung cấp năng lượng cho tế bào","Chất khoáng vi lượng mà cơ thể cần với lượng rất nhỏ","Chất xúc tác sinh học (phần lớn có bản chất protein), giúp các phản ứng sinh hoá trong cơ thể xảy ra nhanh ngay ở điều kiện nhiệt độ và áp suất thường"],"a":"Chất xúc tác sinh học (phần lớn có bản chất protein), giúp các phản ứng sinh hoá trong cơ thể xảy ra nhanh ngay ở điều kiện nhiệt độ và áp suất thường","h":"Nhờ có chúng, hàng nghìn phản ứng trong cơ thể diễn ra nhịp nhàng ở 37°C.","e":"Enzyme là chất xúc tác sinh học, phần lớn là protein, có tính đặc hiệu cao: mỗi enzyme thường xúc tác cho một hoặc một số phản ứng nhất định (như amylase thuỷ phân tinh bột, pepsin phân giải protein). Enzyme giúp phản ứng sinh hoá xảy ra nhanh ở điều kiện nhẹ nhàng của cơ thể.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về polymer?","o":["Polymer là hợp chất có phân tử khối rất lớn, gồm nhiều mắt xích lặp lại liên kết với nhau; phân tử nhỏ ban đầu tạo nên polymer gọi là monomer","Polymer là hợp chất chỉ gồm đúng một mắt xích duy nhất","Polymer là tên gọi chung của mọi kim loại và hợp kim","Mọi polymer trong đời sống đều có nguồn gốc tự nhiên"],"a":"Polymer là hợp chất có phân tử khối rất lớn, gồm nhiều mắt xích lặp lại liên kết với nhau; phân tử nhỏ ban đầu tạo nên polymer gọi là monomer","h":"'Poly' trong tiếng Hy Lạp nghĩa là 'nhiều'.","e":"Polymer (chất cao phân tử) có phân tử khối từ vài nghìn đến vài triệu, phân tử gồm nhiều đơn vị nhỏ (mắt xích) lặp lại. Monomer là phân tử nhỏ ban đầu; khi nhiều monomer liên kết với nhau sẽ tạo thành polymer như nhựa, cao su, tơ.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Điểm khác nhau cơ bản giữa phản ứng trùng hợp và phản ứng trùng ngưng là gì?","o":["Phản ứng trùng hợp luôn kèm theo tách ra phân tử nước","Trong trùng hợp, các monomer kết hợp trực tiếp thành polymer mà không tách phân tử nhỏ; trong trùng ngưng, quá trình tạo polymer kèm theo tách ra phân tử nhỏ như nước","Phản ứng trùng ngưng chỉ xảy ra với monomer có liên kết đôi C=C","Cả hai phản ứng đều tạo ra muối và nước như nhau"],"a":"Trong trùng hợp, các monomer kết hợp trực tiếp thành polymer mà không tách phân tử nhỏ; trong trùng ngưng, quá trình tạo polymer kèm theo tách ra phân tử nhỏ như nước","h":"Polyethylene (PE) từ ethylene là ví dụ trùng hợp; tơ nilon-6,6 là ví dụ trùng ngưng.","e":"Trùng hợp: n monomer kết hợp thành một phân tử polymer, không có sản phẩm phụ nhỏ (ví dụ n CH2=CH2 → PE). Trùng ngưng: các monomer kết hợp đồng thời tách ra phân tử nhỏ (thường là H2O) ở mỗi liên kết mới, như khi tổng hợp nilon-6,6 hay tơ lapsan.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây là đúng về sử dụng và xử lí các loại nhựa PE, PVC, PP trong đời sống?","o":["Đốt rác thải nhựa ngoài trời là cách tái chế đơn giản và an toàn nhất","Mọi loại nhựa đều giống nhau nên dùng bất kì loại nào đựng thức ăn nóng cũng được","Dùng PP làm hộp đựng thực phẩm, PE làm túi và màng bọc, PVC làm ống dẫn nước; nhựa thải cần được phân loại, thu gom tái chế vì rất khó phân huỷ trong môi trường","Chôn nhựa xuống đất một thời gian ngắn là nhựa sẽ phân huỷ hết"],"a":"Dùng PP làm hộp đựng thực phẩm, PE làm túi và màng bọc, PVC làm ống dẫn nước; nhựa thải cần được phân loại, thu gom tái chế vì rất khó phân huỷ trong môi trường","h":"Mỗi loại nhựa có tính chất riêng, phù hợp với từng nhu cầu sử dụng khác nhau, và nhựa rất bền trong môi trường.","e":"PE mềm dẻo nên làm túi, màng bọc; PVC cứng, bền hoá chất nên làm ống nước, vỏ dây điện; PP chịu nhiệt tốt hơn nên thường làm hộp đựng thực phẩm. Nhựa khó phân huỷ tự nhiên (hàng trăm năm) và đốt cháy sinh khí độc, vì vậy cần phân loại, thu gom để tái chế và hạn chế nhựa dùng một lần.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về cao su?","o":["Cao su tự nhiên được tổng hợp hoàn toàn từ dầu mỏ trong nhà máy","Cao su là vật liệu cứng, giòn, hoàn toàn không có tính đàn hồi","Trộn lưu huỳnh vào cao su (lưu hoá) làm cao su mềm nhũn và dễ nóng chảy hơn","Cao su tự nhiên lấy từ mủ cây cao su; lưu hoá (đun với lưu huỳnh) giúp cao su bền và đàn hồi tốt hơn; ngoài ra con người còn sản xuất cao su tổng hợp từ dầu mỏ"],"a":"Cao su tự nhiên lấy từ mủ cây cao su; lưu hoá (đun với lưu huỳnh) giúp cao su bền và đàn hồi tốt hơn; ngoài ra con người còn sản xuất cao su tổng hợp từ dầu mỏ","h":"Lốp xe bền và đàn hồi được là nhờ công đoạn lưu hoá.","e":"Cao su tự nhiên là polymer của isoprene, lấy từ mủ cây cao su. Cao su chưa lưu hoá mềm, dính khi nóng và giòn khi lạnh; khi lưu hoá với lưu huỳnh, các mạch polymer được nối với nhau bằng cầu nối lưu huỳnh nên cao su bền, đàn hồi tốt — dùng làm lốp xe, găng tay. Cao su tổng hợp (như cao su buna) được sản xuất từ các hoá chất dầu mỏ.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Điểm khác nhau về nguồn gốc giữa tơ tằm và tơ nilon là gì?","o":["Tơ tằm là tơ tự nhiên do con tằm nhả ra (bản chất là protein), còn tơ nilon là tơ tổng hợp do con người tạo ra từ hoá chất","Tơ nilon là tơ tự nhiên lấy từ sợi cây bông","Tơ tằm được tổng hợp trong các nhà máy hoá chất lớn","Cả tơ tằm và tơ nilon đều có nguồn gốc từ dầu mỏ"],"a":"Tơ tằm là tơ tự nhiên do con tằm nhả ra (bản chất là protein), còn tơ nilon là tơ tổng hợp do con người tạo ra từ hoá chất","h":"Một loại tơ gắn với nghề nuôi tằm truyền thống, một loại ra đời trong phòng thí nghiệm.","e":"Tơ tằm là tơ thiên nhiên, do con tằm nhả ra, có bản chất protein. Tơ nilon (nylon) là tơ tổng hợp thuộc nhóm tơ polyamide, được con người tổng hợp từ các hoá chất (vốn có nguồn gốc dầu mỏ). Hai loại tơ này khác nhau rõ rệt về nguồn gốc và tính chất.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Vỏ thuyền, cánh máy bay, bồn chứa hoá chất thường được làm bằng vật liệu composite (ví dụ sợi thuỷ tinh kết hợp nhựa). Ưu điểm của vật liệu composite là gì?","o":["Composite là kim loại nguyên chất nên nhẹ nhất trong các vật liệu","Composite kết hợp vật liệu nền (nhựa) và vật liệu cốt (sợi) nên vừa nhẹ vừa bền, chịu ăn mòn tốt — vượt trội hơn từng thành phần riêng lẻ","Composite tan được trong nước nên khi hỏng rất dễ tái chế","Composite chỉ là nhựa tái chế ép lại nên giá rẻ nhưng rất yếu"],"a":"Composite kết hợp vật liệu nền (nhựa) và vật liệu cốt (sợi) nên vừa nhẹ vừa bền, chịu ăn mòn tốt — vượt trội hơn từng thành phần riêng lẻ","h":"Hãy nghĩ đến sự kết hợp: nhựa cho độ bền hoá học, sợi cho độ cứng và chịu lực.","e":"Vật liệu composite gồm hai thành phần chính: vật liệu nền (thường là nhựa polymer) và vật liệu cốt (sợi thuỷ tinh, sợi carbon, hạt...). Sự kết hợp tạo ra vật liệu nhẹ, bền cơ học, chịu ăn mòn và cách điện tốt — được dùng làm vỏ thuyền, thân máy bay, bồn chứa, gậy thể thao...","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Tính chất hoá học chung, đặc trưng nhất của kim loại là gì?","o":["Tính oxi hoá mạnh: kim loại dễ nhận thêm electron","Mọi kim loại đều tác dụng mãnh liệt với nước ở nhiệt độ thường","Tính khử: kim loại dễ nhường electron; nhiều kim loại (đứng trước hydrogen) tác dụng với dung dịch acid loãng như HCl, H2SO4 loãng tạo muối và giải phóng khí H2","Kim loại không bao giờ phản ứng với oxygen dù đun nóng"],"a":"Tính khử: kim loại dễ nhường electron; nhiều kim loại (đứng trước hydrogen) tác dụng với dung dịch acid loãng như HCl, H2SO4 loãng tạo muối và giải phóng khí H2","h":"Nguyên tử kim loại có ít electron lớp ngoài cùng và dễ mất chúng.","e":"Tính chất hoá học đặc trưng của kim loại là tính khử (dễ nhường electron): kim loại tác dụng với phi kim (oxygen, chlorine...), với dung dịch acid (kim loại đứng trước H trong dãy hoạt động tác dụng với HCl, H2SO4 loãng tạo muối + H2), và với dung dịch muối của kim loại yếu hơn.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Dựa vào dãy hoạt động hoá học của kim loại, phát biểu nào sau đây đúng?","o":["Vàng (Au) là kim loại hoạt động hoá học mạnh nhất","Đồng (Cu) đẩy được sắt (Fe) ra khỏi dung dịch muối sắt","Kim loại càng đứng cuối dãy thì càng dễ bị oxi hoá","Kim loại đứng trước (trừ các kim loại kiềm, kiềm thổ) có thể đẩy kim loại đứng sau ra khỏi dung dịch muối của nó, ví dụ sắt đẩy được đồng khỏi dung dịch CuSO4"],"a":"Kim loại đứng trước (trừ các kim loại kiềm, kiềm thổ) có thể đẩy kim loại đứng sau ra khỏi dung dịch muối của nó, ví dụ sắt đẩy được đồng khỏi dung dịch CuSO4","h":"Thứ tự quen thuộc: K, Na, Ca, Mg, Al, Zn, Fe, ..., Cu, Ag, Au.","e":"Trong dãy hoạt động hoá học, kim loại đứng trước mạnh hơn và đẩy được kim loại đứng sau ra khỏi dung dịch muối (Fe + CuSO4 → FeSO4 + Cu). Đồng đứng sau sắt nên không đẩy được sắt; vàng đứng gần cuối dãy nên rất trơ, khó bị oxi hoá.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Cho pin điện hoá Zn–Cu hoạt động một thời gian (điện cực zinc nhúng trong dung dịch ZnSO4, điện cực copper nhúng trong dung dịch CuSO4, hai điện cực nối bằng dây dẫn). Khối lượng hai điện cực thay đổi thế nào?","o":["Điện cực zinc (cực âm) mòn dần vì Zn bị oxi hoá thành Zn2+ đi vào dung dịch; điện cực copper (cực dương) dày lên vì ion Cu2+ bị khử thành Cu bám vào","Điện cực copper mòn dần, điện cực zinc dày lên","Cả hai điện cực đều bị mòn dần với tốc độ như nhau","Không điện cực nào thay đổi, chỉ có dung dịch bị đổi màu"],"a":"Điện cực zinc (cực âm) mòn dần vì Zn bị oxi hoá thành Zn2+ đi vào dung dịch; điện cực copper (cực dương) dày lên vì ion Cu2+ bị khử thành Cu bám vào","h":"Ở cực âm xảy ra quá trình oxi hoá, ở cực dương xảy ra quá trình khử.","e":"Trong pin điện hoá, cực âm là nơi xảy ra sự oxi hoá: Zn → Zn2+ + 2e nên điện cực zinc mòn dần. Electron chạy qua dây dẫn sang cực dương, tại đó Cu2+ + 2e → Cu bám lên điện cực copper làm nó dày lên. Nhờ dòng electron này mà pin sinh ra dòng điện.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Khi điện phân dung dịch muối ăn (NaCl) bão hoà có màng ngăn, sản phẩm thu được ở hai điện cực là gì?","o":["Ở cực âm thu được sodium kim loại, ở cực dương thu được oxygen","Ở cực âm thu được khí hydrogen và dung dịch xút (NaOH) tạo thành quanh cực; ở cực dương thu được khí chlorine","Ở cả hai cực đều thu được dung dịch acid HCl","Dung dịch muối ăn không dẫn điện nên không thể điện phân được"],"a":"Ở cực âm thu được khí hydrogen và dung dịch xút (NaOH) tạo thành quanh cực; ở cực dương thu được khí chlorine","h":"Đây là quá trình công nghiệp clo – kiềm rất quan trọng.","e":"Điện phân dung dịch NaCl có màng ngăn: tại cực âm (cathode), nước bị khử tạo khí H2 và ion OH- nên quanh cực âm hình thành dung dịch NaOH (xút); tại cực dương (anode), ion Cl- bị oxi hoá tạo khí Cl2. Màng ngăn giữ cho Cl2 không tác dụng trở lại với NaOH. Đây là nền tảng của công nghiệp sản xuất xút – chlorine.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Ba chiếc đinh sắt giống hệt nhau được để trong ba điều kiện: (1) ngâm trong dầu ăn, (2) để trong không khí thật khô có chất hút ẩm, (3) ngập một nửa trong nước, phần còn lại tiếp xúc không khí. Sau vài ngày, đinh nào bị gỉ nhiều nhất và vì sao?","o":["Đinh (1), vì dầu ăn có chứa acid làm sắt bị ăn mòn","Đinh (2), vì không khí khô chứa nhiều oxygen nhất","Đinh (3), vì nó tiếp xúc đồng thời với cả nước và oxygen trong không khí — hai điều kiện cần thiết cho sự ăn mòn (gỉ) của sắt","Cả ba đinh gỉ như nhau vì cùng làm bằng sắt"],"a":"Đinh (3), vì nó tiếp xúc đồng thời với cả nước và oxygen trong không khí — hai điều kiện cần thiết cho sự ăn mòn (gỉ) của sắt","h":"Sắt gỉ là quá trình ăn mòn điện hoá cần đồng thời hai tác nhân.","e":"Sự gỉ của sắt xảy ra khi sắt tiếp xúc đồng thời với oxygen và nước (hơi ẩm). Đinh (1) bị dầu cách li khỏi nước và không khí; đinh (2) thiếu nước; chỉ đinh (3) có đủ cả nước lẫn không khí nên gỉ nhanh và nhiều nhất. Đây là cơ sở của các biện pháp chống gỉ như sơn, bôi dầu mỡ.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Biện pháp nào sau đây KHÔNG phải là cách bảo vệ kim loại khỏi bị ăn mòn?","o":["Sơn phủ hoặc bôi dầu mỡ lên bề mặt kim loại","Mạ một lớp kim loại bền như kẽm, crom lên bề mặt","Chế tạo hợp kim chống ăn mòn như thép không gỉ","Ngâm vật bằng sắt lâu dài trong nước biển để 'rèn' cho sắt cứng hơn"],"a":"Ngâm vật bằng sắt lâu dài trong nước biển để 'rèn' cho sắt cứng hơn","h":"Hãy nhớ hai điều kiện gây gỉ: nước và không khí — nước biển còn chứa muối làm ăn mòn nhanh hơn.","e":"Các cách bảo vệ kim loại gồm: phủ bề mặt (sơn, dầu mỡ, mạ), dùng hợp kim chống ăn mòn (thép không gỉ), và phương pháp điện hoá (gắn kim loại hi sinh). Ngâm sắt trong nước biển lại làm sắt ăn mòn rất nhanh vì nước biển chứa muối, là môi trường điện li mạnh.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Người ta thường gắn các tấm zinc (kẽm) vào vỏ tàu biển bằng thép và định kì thay các tấm này. Cách làm đó bảo vệ vỏ tàu theo nguyên lí nào?","o":["Zinc hoạt động hoá học mạnh hơn sắt nên bị ăn mòn trước (đóng vai trò kim loại hi sinh), nhờ đó thép của vỏ tàu được bảo vệ","Zinc nhẹ hơn thép nên giúp con tàu nổi tốt hơn","Zinc cứng hơn thép nên các tấm zinc gia cố cho vỏ tàu chắc chắn","Zinc tạo lớp sơn tự nhiên ngăn nước biển chạm vào vỏ tàu"],"a":"Zinc hoạt động hoá học mạnh hơn sắt nên bị ăn mòn trước (đóng vai trò kim loại hi sinh), nhờ đó thép của vỏ tàu được bảo vệ","h":"Đây là phương pháp bảo vệ điện hoá bằng 'kim loại hi sinh'.","e":"Khi zinc tiếp xúc điện với thép trong nước biển, một pin điện hoá hình thành; zinc hoạt động mạnh hơn sắt nên đóng vai trò cực âm và bị ăn mòn dần, còn thép được bảo vệ. Khi tấm zinc mòn nhiều, người ta thay tấm mới — đó là phương pháp bảo vệ kim loại bằng kim loại hi sinh, cũng dùng cho đường ống ngầm và công trình biển.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về hợp kim?","o":["Thép không gỉ là sắt nguyên chất 100% nên không bị gỉ","Thép không gỉ là hợp kim của sắt với chromium (và thường thêm nickel) nên chống ăn mòn tốt; duralumin là hợp kim nhẹ của aluminium dùng trong chế tạo máy bay","Mọi hợp kim đều mềm và dễ nóng chảy hơn kim loại thành phần","Duralumin là hợp kim của sắt và carbon dùng làm đường ray"],"a":"Thép không gỉ là hợp kim của sắt với chromium (và thường thêm nickel) nên chống ăn mòn tốt; duralumin là hợp kim nhẹ của aluminium dùng trong chế tạo máy bay","h":"Hãy nhớ hai hợp kim nổi tiếng: một loại chống gỉ, một loại nhẹ dùng cho hàng không.","e":"Hợp kim là vật liệu gồm một kim loại với các nguyên tố khác. Thép không gỉ chứa thêm chromium (thường cả nickel) nên bề mặt tạo lớp oxide bền chống ăn mòn. Duralumin gồm aluminium với đồng, magnesium, manganese... nhẹ mà cứng, được dùng nhiều trong ngành hàng không.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Một gia đình có thói quen vứt pin cũ (pin tiểu, pin đồng hồ) chung với rác sinh hoạt để chôn lấp. Việc làm này nguy hại thế nào và nên xử lí ra sao?","o":["Hoàn toàn vô hại vì vỏ pin rất kín, kim loại bên trong không bao giờ lọt ra ngoài","Nên đốt pin cùng rác vì nhiệt độ cao sẽ làm bay hơi hết các chất độc","Pin thải chứa các kim loại nặng như chì, thuỷ ngân, cadmium; nếu chôn lấp chung, chúng có thể ngấm vào đất và nước, tích luỹ qua chuỗi thức ăn gây hại sức khoẻ — cần thu gom riêng, đưa tới điểm thu hồi để xử lí chuyên biệt","Kim loại nặng trong pin sẽ tự phân huỷ hết trong đất sau vài tuần"],"a":"Pin thải chứa các kim loại nặng như chì, thuỷ ngân, cadmium; nếu chôn lấp chung, chúng có thể ngấm vào đất và nước, tích luỹ qua chuỗi thức ăn gây hại sức khoẻ — cần thu gom riêng, đưa tới điểm thu hồi để xử lí chuyên biệt","h":"Thuỷ ngân và chì là những kim loại nặng rất độc và tích luỹ lâu dài trong cơ thể.","e":"Nhiều loại pin chứa kim loại nặng độc hại như thuỷ ngân (Hg), chì (Pb), cadmium (Cd). Vỏ pin bị ăn mòn theo thời gian sẽ làm các chất này rò rỉ vào đất, nước ngầm rồi tích luỹ trong cơ thể sinh vật và con người qua chuỗi thức ăn, gây tổn thương thần kinh, thận... Vì vậy pin thải thuộc nhóm rác thải nguy hại, phải thu gom riêng tại các điểm thu hồi để xử lí đúng quy trình.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Các kim loại kiềm như sodium (Na) và potassium (K) có đặc điểm nào sau đây?","o":["Rất cứng, nặng và hầu như không phản ứng với nước","Mềm (có thể cắt bằng dao), nhẹ và phản ứng mạnh với nước, tạo dung dịch kiềm và khí hydrogen","Không phản ứng với oxygen trong không khí","Là kim loại quý, rất khó bị oxi hoá"],"a":"Mềm (có thể cắt bằng dao), nhẹ và phản ứng mạnh với nước, tạo dung dịch kiềm và khí hydrogen","h":"Thả một mẩu nhỏ sodium vào nước, nó chạy trên mặt nước, tan nhanh kèm sủi bọt khí.","e":"Kim loại kiềm rất hoạt động: mềm, nhẹ, phản ứng mạnh với nước theo phương trình 2Na + 2H2O -> 2NaOH + H2, tạo dung dịch kiềm và giải phóng khí hydrogen. Vì vậy chúng được bảo quản trong dầu hoả.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Nước cứng là loại nước có đặc điểm gì?","o":["Chứa nhiều ion Ca2+ và Mg2+","Chứa nhiều ion Na+ và K+","Chứa nhiều khí CO2 hoà tan","Có pH rất thấp, mang tính acid mạnh"],"a":"Chứa nhiều ion Ca2+ và Mg2+","h":"Nước cứng là nguyên nhân gây đóng cặn trắng CaCO3 trong ấm đun nước.","e":"Nước cứng là nước chứa nhiều ion calcium (Ca2+) và magnesium (Mg2+). Tuỳ thành phần muối gây cứng, người ta chia nước cứng thành nước cứng tạm thời, vĩnh cửu và toàn phần.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Tác hại nào sau đây là của nước cứng trong đời sống và sản xuất?","o":["Làm cho nước uống có vị ngọt, dễ uống hơn","Giúp xà phòng tạo nhiều bọt và giặt sạch hơn","Đóng cặn trong ấm đun nước, nồi hơi và làm tốn xà phòng khi giặt","Làm tăng độ bền cho đường ống kim loại"],"a":"Đóng cặn trong ấm đun nước, nồi hơi và làm tốn xà phòng khi giặt","h":"Hãy để ý lớp cặn trắng đóng dưới đáy ấm đun nước sau một thời gian sử dụng.","e":"Nước cứng gây nhiều tác hại: đóng cặn trong ấm đun, nồi hơi làm tốn nhiên liệu, giảm hiệu suất và tuổi thọ thiết bị; khi giặt, ion Ca2+ và Mg2+ kết tủa với xà phòng làm tốn xà phòng và quần áo mau cứng, xỉn màu.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Nước cứng tạm thời chứa các muối Ca(HCO3)2 và Mg(HCO3)2. Cách đơn giản nào sau đây làm mềm được nước cứng tạm thời?","o":["Để yên nước thật lâu cho các muối tự lắng xuống","Cho thêm nước đá vào để làm lạnh nước","Lọc nước qua giấy lọc nhiều lần","Đun sôi nước để các muối bicarbonate chuyển thành kết tủa CaCO3, MgCO3 rồi lọc bỏ"],"a":"Đun sôi nước để các muối bicarbonate chuyển thành kết tủa CaCO3, MgCO3 rồi lọc bỏ","h":"Khi đun sôi, Ca(HCO3)2 bị phân huỷ tạo kết tủa trắng — đó chính là cặn trong ấm đun nước.","e":"Đun sôi làm muối bicarbonate phân huỷ: Ca(HCO3)2 -> CaCO3 (kết tủa) + CO2 + H2O, loại bỏ được ion Ca2+ và Mg2+ khỏi nước. Cách này chỉ hiệu quả với nước cứng tạm thời.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Các kim loại chuyển tiếp dãy thứ nhất như iron (Fe), copper (Cu), chromium (Cr) có đặc điểm chung nổi bật nào sau đây?","o":["Ion của chúng thường có màu và nhiều hợp chất của chúng có tính xúc tác","Chúng đều là chất lỏng ở nhiệt độ thường","Chúng không tạo được hợp chất có màu","Chúng rất trơ, hầu như không tham gia phản ứng hoá học"],"a":"Ion của chúng thường có màu và nhiều hợp chất của chúng có tính xúc tác","h":"Dung dịch CuSO4 có màu xanh lam, dung dịch muối iron(III) có màu vàng nâu.","e":"Kim loại chuyển tiếp có nhiều số oxi hoá khác nhau; ion của chúng thường có màu đặc trưng và nhiều đơn chất, hợp chất của chúng đóng vai trò chất xúc tác quan trọng trong công nghiệp (ví dụ Fe xúc tác tổng hợp NH3).","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi cho dung dịch ammonia dư vào dung dịch CuSO4, tạo thành phức chất [Cu(NH3)4]2+ có màu xanh lam đậm. Trong phức chất này, nguyên tử trung tâm và phối tử lần lượt là","o":["Nguyên tử trung tâm là N, phối tử là Cu2+","Nguyên tử trung tâm là Cu2+, phối tử là các phân tử NH3","Nguyên tử trung tâm là H, phối tử là NH3","Nguyên tử trung tâm là NH3, phối tử là Cu2+"],"a":"Nguyên tử trung tâm là Cu2+, phối tử là các phân tử NH3","h":"Phối tử là các phân tử hoặc ion liên kết xung quanh nguyên tử (ion) kim loại ở trung tâm.","e":"Phức chất gồm nguyên tử trung tâm là ion kim loại (ở đây là Cu2+) liên kết với các phối tử bao quanh (ở đây là 4 phân tử NH3). Phức [Cu(NH3)4]2+ có màu xanh lam đậm đặc trưng, dùng để nhận biết ion Cu2+.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Phức chất cisplatin được ứng dụng quan trọng nào trong y học?","o":["Làm thuốc gây mê trong phẫu thuật","Làm chất cản quang khi chụp X-quang","Dùng làm thuốc điều trị ung thư","Dùng làm thuốc bổ sung sắt cho người thiếu máu"],"a":"Dùng làm thuốc điều trị ung thư","h":"Cisplatin là phức chất của platinum (Pt), nổi tiếng trong điều trị các khối u.","e":"Cisplatin là phức chất của Pt được dùng làm thuốc hoá trị điều trị ung thư. Trong cơ thể người cũng có các phức chất quan trọng, như hemoglobin (phức chất chứa Fe) vận chuyển oxygen trong máu.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong luyện gang, thép, người ta dùng carbon monoxide (CO) để khử iron oxide trong quặng ở nhiệt độ cao trong lò cao. Phương pháp tách kim loại này thuộc loại nào?","o":["Phương pháp điện phân","Phương pháp thuỷ luyện","Phương pháp cơ học","Phương pháp nhiệt luyện"],"a":"Phương pháp nhiệt luyện","h":"Tên phương pháp gắn với việc dùng nhiệt độ cao cùng chất khử như C, CO, H2.","e":"Nhiệt luyện là phương pháp dùng các chất khử như C, CO, H2 để khử oxide kim loại ở nhiệt độ cao, áp dụng cho các kim loại có độ hoạt động trung bình và yếu như Fe, Zn, Cu.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Aluminium (nhôm) là kim loại hoạt động mạnh nên không tách được bằng phương pháp nhiệt luyện thông thường. Trong công nghiệp, nhôm được sản xuất bằng phương pháp nào?","o":["Điện phân nóng chảy aluminium oxide (Al2O3)","Dùng CO khử Al2O3 ở nhiệt độ cao","Điện phân dung dịch muối AlCl3","Nung Al2O3 với than cốc trong lò cao như luyện gang"],"a":"Điện phân nóng chảy aluminium oxide (Al2O3)","h":"Các kim loại hoạt động mạnh như K, Na, Ca, Al chỉ có thể tách ra bằng cách điện phân nóng chảy hợp chất của chúng.","e":"Kim loại hoạt động mạnh phải dùng phương pháp điện phân nóng chảy. Nhôm được sản xuất bằng cách điện phân Al2O3 nóng chảy (có thêm criolit để hạ nhiệt độ nóng chảy và tăng độ dẫn điện).","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Cho thế điện cực chuẩn: E°(Zn2+/Zn) = -0,76 V và E°(Cu2+/Cu) = +0,34 V. Trong pin điện hoá Zn-Cu, Zn là anot, Cu là catot và E°(pin) = E°(catot) - E°(anot). Sức điện động chuẩn của pin Zn-Cu là","o":["0,42 V","1,10 V","-1,10 V","0,76 V"],"a":"1,10 V","h":"Lấy thế điện cực của đồng trừ đi thế điện cực của kẽm: 0,34 - (-0,76).","e":"E°(pin) = E°(catot) - E°(anot) = E°(Cu2+/Cu) - E°(Zn2+/Zn) = 0,34 - (-0,76) = 1,10 V.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Khi thuỷ phân hoàn toàn saccharose (đường mía) trong môi trường acid loãng, đun nóng, ta thu được những chất nào?","o":["Hai phân tử glucose","Glucose và fructose","Chỉ tạo thành glucose và nước","Tinh bột và cellulose"],"a":"Glucose và fructose","h":"Saccharose là đường đôi, gồm hai đơn vị đường đơn khác nhau ghép lại.","e":"Saccharose là một đường đôi (disaccharide). Khi thuỷ phân nhờ xúc tác acid (hoặc enzyme invertase), một phân tử saccharose tách ra thành một phân tử glucose và một phân tử fructose — đều là đường đơn có thể hấp thụ trực tiếp.","t":"hoa-lop12","g":12,"l":"nhe-nhang"},{"p":"Điện phân dung dịch copper(II) sulfate (CuSO4) bằng điện cực trơ (graphite) trong một thời gian. Hiện tượng nào sau đây đúng?","o":["Kim loại copper (Cu) bám trên điện cực catot, khí oxygen (O2) thoát ra ở điện cực anot","Khí hydrogen thoát ra ở catot, khí chlorine thoát ra ở anot","Copper bám ở anot, khí oxygen thoát ra ở catot","Không có chất nào tạo thành vì dung dịch muối không bị điện phân"],"a":"Kim loại copper (Cu) bám trên điện cực catot, khí oxygen (O2) thoát ra ở điện cực anot","h":"Ion kim loại di chuyển về catot và bị khử thành kim loại; ở anot, nước nhường electron tạo khí oxygen.","e":"Khi điện phân dung dịch CuSO4 với điện cực trơ: ở catot (cực âm), ion Cu²⁺ nhận electron tạo thành kim loại copper bám trên điện cực (Cu²⁺ + 2e → Cu); ở anot (cực dương), nước bị oxi hoá tạo khí oxygen thoát ra. Dung dịch dần mất màu xanh do nồng độ Cu²⁺ giảm.","t":"hoa-lop12","g":12,"l":"thu-thach"},{"p":"Cấu tạo của tinh thể kim loại gồm những thành phần nào sau đây?","o":["Các phân tử kim loại liên kết với nhau bằng liên kết cộng hoá trị","Các ion dương kim loại sắp xếp có trật tự và các electron tự do chuyển động trong toàn bộ tinh thể","Các nguyên tử kim loại đứng yên hoàn toàn, mọi electron đều gắn chặt với từng nguyên tử","Các ion âm và ion dương kim loại xếp xen kẽ như trong tinh thể muối ăn"],"a":"Các ion dương kim loại sắp xếp có trật tự và các electron tự do chuyển động trong toàn bộ tinh thể","h":"Hãy nghĩ xem vì sao kim loại dẫn điện tốt: trong tinh thể kim loại có loại hạt mang điện nào chuyển động tự do?","e":"Trong tinh thể kim loại, các nguyên tử kim loại nhường electron hoá trị tạo thành các ion dương nằm tại các nút mạng tinh thể, còn các electron tách ra trở thành electron tự do, chuyển động trong toàn tinh thể như 'keo' gắn kết các ion. Chính các electron tự do này giúp kim loại dẫn điện, dẫn nhiệt và có tính dẻo.","t":"hoa-lop12","g":12,"l":"nhe-nhang"}];